<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Loading...</title>

    <!-- Include Bootstrap and Bootswatch Lux theme -->
    <link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.0/dist/css/bootstrap.min.css" rel="stylesheet">
    <link href="https://cdn.jsdelivr.net/npm/bootswatch@5.3.0/dist/lux/bootstrap.min.css" rel="stylesheet">

    <!-- Include the Showdown library for Markdown to HTML conversion -->
    <script src="https://cdnjs.cloudflare.com/ajax/libs/showdown/1.9.1/showdown.min.js"></script>
</head>
<body class="bg-light">

<header class="bg-primary text-white text-center py-3">
    <h1 id="post-title" class="display-4">Loading...</h1>
</header>

<div class="container my-4" id="post-content"></div>

<footer class="bg-primary text-white text-center py-3">
    <p>&copy; 2024 Your Website</p>
</footer>

<script>
    // Fetch the Markdown content
    fetch('sample-post.md')
        .then(response => response.text())
        .then(markdown => {
            // Extract metadata from Markdown front matter
            const metadata = extractMetadata(markdown);

            // Set document title
            document.title = metadata.title;

            // Set post title
            document.getElementById('post-title').innerText = metadata.title;

            // Convert Markdown to HTML (excluding front matter)
            const contentWithoutMetadata = markdown.split('---').slice(2).join('---');
            const converter = new showdown.Converter();
            const html = converter.makeHtml(contentWithoutMetadata);

            // Display the HTML content in the post-content div
            document.getElementById('post-content').innerHTML = html;

            // Set cover image
            const coverImg = document.createElement('img');
            coverImg.src = metadata.cover;
            coverImg.alt = 'Cover Image';
            coverImg.className = 'img-fluid my-4';
            document.getElementById('post-content').insertBefore(coverImg, document.getElementById('post-content').firstChild);

            // Set tags with hyperlinks
            const tagsElement = document.createElement('p');
            tagsElement.innerHTML = '<strong>Tags:</strong> ' + metadata.tags.map(tag => `<a href="#">${tag}</a>`).join(', ');
            document.getElementById('post-content').insertBefore(tagsElement, document.getElementById('post-content').firstChild);

            // Set date
            const dateElement = document.createElement('p');
            dateElement.innerHTML = '<strong>Date:</strong> ' + new Date(metadata.datePublished).toDateString();
            document.getElementById('post-content').insertBefore(dateElement, document.getElementById('post-content').firstChild);
        })
        .catch(error => console.error('Error fetching Markdown:', error));

    function extractMetadata(markdown) {
        const frontMatter = markdown.split('---')[1];
        const metadataLines = frontMatter.split('\n').filter(line => line.trim() !== '');

        const metadata = {};
        metadataLines.forEach(line => {
            const [key, value] = line.split(':').map(item => item.trim());
            metadata[key] = value;
        });

        return metadata;
    }
</script>

</body>
</html>

