package main

import (
	"io/ioutil"
	"os"
	"os/exec"
	"path/filepath"
)

func main() {
	if len(os.Args) < 2 {
		panic("Usage: goscript <file>")
	}

	content, err := ioutil.ReadFile(os.Args[1])
	if err != nil {
		panic(err)
	}

	tmpFile, err := ioutil.TempFile("", "goscript*.go")
	if err != nil {
		panic(err)
	}
	defer os.Remove(tmpFile.Name())

	boilerplate := `package main

import (
    "github.com/bitfield/script"
)

func main() {
`

	if _, err = tmpFile.WriteString(boilerplate + string(content) + "\n}\n"); err != nil {
		panic(err)
	}
	tmpFile.Close()

	cmd := exec.Command("go", "run", tmpFile.Name())
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	cmd.Stdin = os.Stdin
	if err := cmd.Run(); err != nil {
		panic(err)
	}
}

