class Particle {
private:
    float x_;
    float y_;
    float z_;
    float vx_;
    float vy_;
    float vz_;
    float mass_;

    Particle(float x, float y, float z, float vx, float vy, float vz, float mass)
        : x_(x), y_(y), z_(z), vx_(vx), vy_(vy), vz_(vz), mass_(mass) {}

public:
    class Builder {
    private:
        float x_;
        float y_;
        float z_;
        float vx_;
        float vy_;
        float vz_;
        float mass_;

    public:
        Builder() = default;

        Builder& setPosition(float x, float y, float z) {
            x_ = x;
            y_ = y;
            z_ = z;
            return *this;
        }

        Builder& setVelocity(float vx, float vy, float vz) {
            vx_ = vx;
            vy_ = vy;
            vz_ = vz;
            return *this;
        }

        Builder& setMass(float mass) {
            mass_ = mass;
            return *this;
        }

        Particle build() {
            return Particle(x_, y_, z_, vx_, vy_, vz_, mass_);
        }
    };

    float x() const { return x_; }

    float y() const { return y_; }

    float z() const { return z_; }

    float vx() const { return vx_; }

    float vy() const { return vy_; }

    float vz() const { return vz_; }

    float mass() const { return mass_; }

    void move(const float dt) {
        x_ += vx_ * dt;
        y_ += vy_ * dt;
        z_ += vz_ * dt;
    }

    void accelerate(const float ax, const float ay, const float az, const float dt) {
        vx_ += ax * dt;
        vy_ += ay * dt;
        vz_ += az * dt;
    }

    float kinetic_energy() const {
        return 0.5 * mass_ * (vx_ * vx_ + vy_ * vy_ + vz_ * vz_);
    }
};

