float total_energy(const std::vector<Particle>& particles, const LennardJones& lennard_jones) {
    float total_kinetic_energy = std::accumulate(particles.begin(), particles.end(), 0.0f, [](float energy, const Particle& particle) {
        return energy + particle.kinetic_energy();
    });

    float total_potential_energy = std::accumulate(particles.begin(), particles.end(), 0.0f, [&](float energy, const Particle& particle) {
        return std::accumulate(particles.begin(), particles.end(), energy, [&](float sub_energy, const Particle& other_particle) {
            if (&particle != &other_particle) {
                float r = distance(particle, other_particle);
                return sub_energy + lennard_jones.energy(r);
            }
            return sub_energy;
        });
    });

    return total_kinetic_energy + 0.5f * total_potential_energy;
}

