    float total_mass = std::accumulate(particles.begin(), particles.end(), 0.0f, [](float mass, const Particle& particle) {
        return mass + particle.mass();
    });

    float x = std::accumulate(particles.begin(), particles.end(), 0.0f, [&](float sum, const Particle& particle) {
        return sum + particle.x() * particle.mass();
