                this.y = y;
                this.size = 2;
                this.color = `hsl(120, 100%, 50%)`;
            }

            drawPetals(n, radius) {
                const angle = Math.PI * 2 / n;
                for (let i = 0; i < n; i++) {
                    const petalX = this.x + radius * Math.cos(angle * i);
