  for (var i = 0; i < 100; i++) {
    createParticle(event.pageX, event.pageY);
  }
});

function createParticle(x, y) {
  // Create a custom particle element
  var particle = document.createElement('div');
  particle.classList.add('firework');
  document.getElementById('sky').appendChild(particle);

  // Generate a random x, y destination within a distance of 150px from the mouse
  var destinationX = x + (Math.random() - 0.5) * 2 * 150;
  var destinationY = y + (Math.random() - 0.5) * 2 * 150;

  // Calculate the distance to the destination
  var distanceX = Math.abs(destinationX - x);
  var distanceY = Math.abs(destinationY - y);

  // Calculate a random duration for the animation
  var duration = Math.sqrt(Math.pow(distanceX, 2) + Math.pow(distanceY, 2));

  // Apply the styles to the particle
  particle.style.left = x + 'px';
  particle.style.top = y + 'px';
  particle.style.transition = 'all ' + duration + 'ms linear';
  particle.style.transform = 'scale(0)';

  // Apply the destination positions
  setTimeout(function() {
    particle.style.left = destinationX + 'px';
    particle.style.top = destinationY + 'px';
    particle.style.transform = 'scale(1)';
  }, 0);

  // Remove the particle after the animation completes
  setTimeout(function() {
    particle.parentNode.removeChild(particle);
  }, duration);
}

