    guard let cgImage1 = image1.cgImage, let cgImage2 = image2.cgImage,
          let data1 = cgImage1.dataProvider?.data as Data?,
          let data2 = cgImage2.dataProvider?.data as Data? else {
        return 1.0
    }

    let pixelCount = image1.size.width * image1.size.height
    let pixelData1 = data1.map { UnsafeBufferPointer<UInt8>(start: $0, count: data1.count) }
    let pixelData2 = data2.map { UnsafeBufferPointer<UInt8>(start: $0, count: data2.count) }

    var mae: CGFloat = 0.0

    for i in stride(from: 0, to: pixelCount, by: 4) {
        let r1 = pixelData1?[i]
        let g1 = pixelData1?[i + 1]
        let b1 = pixelData1?[i + 2]

        let r2 = pixelData2?[i]
        let g2 = pixelData2?[i + 1]
        let b2 = pixelData2?[i + 2]

        let diffR = abs(CGFloat(r1! - r2!))
        let diffG = abs(CGFloat(g1! - g2!))
        let diffB = abs(CGFloat(b1! - b2!))

        let diff = (diffR + diffG + diffB) / (3 * 255)
        mae += diff
    }

    mae /= pixelCount

    return mae
}

