module FIPO_Memory (
    input clk,              // Clock input
    input rst,              // Reset input
    input load,             // Load input to trigger data capture
    input serial_in,        // Serial input data
    output reg [311:0] parallel_out  // Parallel output of all data
);

// Internal memory to store the serially input data
reg [311:0] data_memory;
// Counter to keep track of the number of bits received
reg [8:0] bit_counter;  // Needs to count up to 312, thus 9 bits are required

always @(posedge clk or posedge rst) begin
    if (rst) begin
        // Reset all registers when rst is high
        data_memory <= 312'b0;
        bit_counter <= 0;
        parallel_out <= 312'b0;
    end else if (load) begin
        // Load the current serial bit into the memory at the position indicated by bit_counter
        if (bit_counter < 312) begin
            data_memory[bit_counter] <= serial_in;
            bit_counter <= bit_counter + 1;
        end else begin
            // Once all bits are received, output them on parallel_out
            parallel_out <= data_memory;
            bit_counter <= 0;  // Reset the counter to allow new data loading
        end
    end
end

endmodule

