def generate_delay_steps(total_delay):
    total_delay = round(total_delay)  # Convert to the nearest integer

    if total_delay <= 1:
        return (1, 1)  # Default values for total_delay of 1 or less

    factors = [1, total_delay]
    for i in range(2, int(total_delay**0.5) + 1):
        if total_delay % i == 0:
            factors.append(i)
            if i != total_delay // i:
                factors.append(total_delay // i)

    factors.sort()

    index = len(factors) * 2 // 3
    part_delay = factors[index]
    iterations = total_delay // part_delay

    return part_delay, iterations

