import processing.serial.*;

Serial myPort;  // Create a Serial object

int[] data = new int[1000];  // An array to store radar data
int dataIndex = 0;          // Index for the data array

void setup() {
  size(800, 400);   // Set the size of the window
  myPort = new Serial(this, Serial.list()[0], 9600);  // Initialize serial communication
  myPort.bufferUntil('\n');  // Read data until a newline character is received
}

void draw() {
  background(255);  // Clear the background

  // Display the radar data as a graph
  for (int i = 0; i < dataIndex - 1; i++) {
    line(i, height - data[i], i + 1, height - data[i + 1]);
  }
}

void serialEvent(Serial p) {
  String dataString = p.readStringUntil('\n');  // Read the data from the Arduino
  if (dataString != null) {
    data[dataIndex] = int(dataString);  // Convert the received data to an integer
    dataIndex++;
  }
}

