use Carp;

sub find_iterator {
    my ($dir) = @_;

    if (!-d $dir) {
        croak "ERROR: $dir is not a directory";
    }

    my $index = 0;
    my $current_path;

    return sub {
        if (!$current_path) {
            while (1) {
                last if $index >= @files;
                my $path = $files[$index++];
                if (-f $path) {
                    $current_path = $path;
                    last;
                }
            }
        }

        my $path = $current_path;
        $current_path = undef;
        return $path;
    };
}

# Example usage:
my $iterator = find_iterator('/path/to/directory');

while (my $file = $iterator->()) {
    # Process each file
    print "$file\n";
}

