use Carp;

sub find_iterator {
    my ($dir) = @_;

    if (!-d $dir) {
        croak "ERROR: $dir is not a directory";
    }

    my $index = 0;
    my @files;

    my $generator = sub {
        if (!@files) {
            _find_recursive($dir, \@files);
        }

        return undef if $index >= @files;

        my $path = $files[$index++];
        return $path;
    };

    return $generator;
}

