        <div id="countdown-bar">
            <div id="countdown-progress"></div>
        </div>
    </div>

    <script>
        // Set the countdown time in seconds
        const countdownTime = 5;

        // Get the countdown elements
        const countdownBar = document.getElementById('countdown-bar');
        const countdownProgress = document.getElementById('countdown-progress');

        // Calculate the width of each second in percentage
        const widthPerSecond = 100 / countdownTime;

        // Update the progress bar every second
        const updateProgressBar = () => {
            const remainingTime = Math.max(0, countdownTime - elapsedSeconds());
            const progressWidth = widthPerSecond * remainingTime;
            countdownProgress.style.width = `${progressWidth}%`;
        };

        // Function to calculate elapsed seconds
        const elapsedSeconds = () => {
            return Math.floor((Date.now() - startTime) / 1000);
        };

        // Start the countdown
        const startTime = Date.now();
        updateProgressBar();
        const countdownInterval = setInterval(() => {
            updateProgressBar();

            // Check if the countdown is complete
            if (elapsedSeconds() >= countdownTime) {
                clearInterval(countdownInterval);
                alert('Countdown completed!');
            }
        }, 1000);
    </script>
