#version 460 core

in vec2 uv;
out vec4 fragColor;

uniform sampler2D depthTex;
uniform vec2 texelSize; // 1/width, 1/height

float getDepth(vec2 uv) {
    return texture(depthTex, uv).r;
}

void main()
{
    float d00 = getDepth(uv + texelSize * vec2(-1, -1));
    float d01 = getDepth(uv + texelSize * vec2( 0, -1));
    float d02 = getDepth(uv + texelSize * vec2( 1, -1));

    float d10 = getDepth(uv + texelSize * vec2(-1,  0));
    float d11 = getDepth(uv + texelSize * vec2( 0,  0));
    float d12 = getDepth(uv + texelSize * vec2( 1,  0));

    float d20 = getDepth(uv + texelSize * vec2(-1,  1));
    float d21 = getDepth(uv + texelSize * vec2( 0,  1));
    float d22 = getDepth(uv + texelSize * vec2( 1,  1));

    float sx =
          d00 + 2.0 * d10 + d20
        - d02 - 2.0 * d12 - d22;

    float sy =
          d00 + 2.0 * d01 + d02
        - d20 - 2.0 * d21 - d22;

    float edge = sqrt(sx*sx + sy*sy);

    // threshold
    if (edge > 0.003)
        fragColor = vec4(1, 1, 1, 1); // outline
    else
        fragColor = vec4(0, 0, 0, 0); // transparent/black
}

