import torch
import torch.nn as nn

class MyModel(nn.Module):
    def __init__(self):
        super().__init__()
        self.conv = nn.ModuleList([
            nn.Conv2d(3, 16, 3),
            nn.Conv2d(16, 32, 3)
        ])
        self.classifier = nn.Linear(32, 10)

    def forward(self, x):
        for layer in self.conv:
            x = layer(x)
        x = x.mean(dim=[2,3])  # global avg pool
        return self.classifier(x)

model = MyModel()

# Optimizer with different LR for conv and classifier
optimizer = torch.optim.Adam([
    {"params": model.classifier.parameters(), "lr": 1e-3, "weight_decay": 0.0},
    {"params": model.conv.parameters(), "lr": 1e-4, "weight_decay": 1e-5},
])

