using Autodesk.Revit.Attributes;
using Autodesk.Revit.DB;
using Autodesk.Revit.UI;
using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Runtime.InteropServices;

[Transaction(TransactionMode.Manual)]
public class SwitchProject : IExternalCommand
{
    // Import necessary Windows API functions
    [DllImport("user32.dll")]
    static extern bool EnumWindows(EnumWindowsProc lpEnumFunc, IntPtr lParam);

    delegate bool EnumWindowsProc(IntPtr hWnd, IntPtr lParam);

    [DllImport("user32.dll", CharSet = CharSet.Auto)]
    static extern int GetWindowText(IntPtr hWnd, System.Text.StringBuilder lpString, int nMaxCount);

    [DllImport("user32.dll", SetLastError = true)]
    static extern uint GetWindowThreadProcessId(IntPtr hWnd, out uint lpdwProcessId);

    [DllImport("user32.dll")]
    static extern bool IsWindowVisible(IntPtr hWnd);

    [DllImport("user32.dll")]
    static extern bool SetForegroundWindow(IntPtr hWnd);

    public Result Execute(ExternalCommandData commandData, ref string message, ElementSet elements)
    {
        UIApplication uiapp = commandData.Application;
        UIDocument uidoc = uiapp.ActiveUIDocument;
        Document currentDoc = uidoc.Document;

        // Get list of open documents excluding the current one and family documents
        var openDocs = uiapp.Application.Documents
            .Cast<Document>()
            .Where(doc => !doc.IsFamilyDocument && doc.Title != currentDoc.Title)
            .ToList();

        if (openDocs.Count == 0)
        {
            TaskDialog.Show("Switch Project", "No other open projects found.");
            return Result.Succeeded;
        }

        // Prepare entries for DataGrid
        var entries = openDocs.Select(doc => new { Title = doc.Title }).ToList();

        var propertyNames = new List<string> { "Title" };

        // Use DataGrid to let user select a project
        var selectedEntries = CustomGUIs.DataGrid(entries, propertyNames, Title: "Select Project");

        if (selectedEntries.Count == 0)
            return Result.Cancelled;

        string selectedProjectTitle = selectedEntries.First().Title;

        // Find the Document corresponding to the selected title
        var selectedDoc = openDocs.FirstOrDefault(doc => doc.Title == selectedProjectTitle);

        if (selectedDoc == null)
        {
            TaskDialog.Show("Error", "Could not find the selected document.");
            return Result.Failed;
        }

        // Get the process ID of Revit
        uint revitProcessId = (uint)System.Diagnostics.Process.GetCurrentProcess().Id;

        // Find the window handle of the selected project
        IntPtr hWnd = FindRevitDocumentWindow(selectedDoc.Title, revitProcessId);

        if (hWnd == IntPtr.Zero)
        {
            TaskDialog.Show("Error", "Could not find the window for the selected project.");
            return Result.Failed;
        }

        // Bring the window to the foreground
        SetForegroundWindow(hWnd);

        // Create UIDocument for the selected document
        UIDocument selectedUIDoc = new UIDocument(selectedDoc);

        // Now, read the log file and activate the last opened view
        string appDataPath = Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData);
        string logFilePath = Path.Combine(appDataPath, "revit-scripts", "LogViewChanges", $"{selectedDoc.Title}");

        if (!File.Exists(logFilePath))
        {
            TaskDialog.Show("Error", "Log file does not exist for the selected project.");
            return Result.Failed;
        }

