        var openDocs = docSet.Cast<Document>()
            .Where(doc => !doc.IsFamilyDocument && !doc.IsLinked && doc.Title != currentDoc.Title)
            .ToList();

        if (openDocs.Count == 0)
        {
            TaskDialog.Show("Switch Project", "No other open projects found.");
            return Result.Succeeded;
        }

        // Prepare entries for DataGrid, including the PathName
        var entries = openDocs.Select(doc => new { Title = doc.Title, PathName = doc.PathName }).ToList();

        var propertyNames = new List<string> { "Title" };

        // Use DataGrid to let user select a project
        var selectedEntries = CustomGUIs.DataGrid(entries, propertyNames, Title: "Select Project");

        if (selectedEntries.Count == 0)
