        string selectedProjectTitle = selectedEntries.First().Title;
        string selectedProjectPath = selectedEntries.First().PathName;

        // Check if the path is valid
        if (string.IsNullOrEmpty(selectedProjectPath) || !File.Exists(selectedProjectPath))
        {
            TaskDialog.Show("Error", "Invalid or inaccessible file path for the selected project.");
            return Result.Failed;
        }

        try
        {
            // Convert the path to a ModelPath
            ModelPath modelPath = ModelPathUtils.ConvertUserVisiblePathToModelPath(selectedProjectPath);
            OpenOptions openOptions = new OpenOptions();

            // Open and activate the document
            UIDocument selectedUIDoc = uiApp.OpenAndActivateDocument(modelPath, openOptions, false);
            Document selectedDoc = selectedUIDoc.Document;

            // Now, read the log file and activate the last opened view
            string appDataPath = Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData);
            string logFilePath = Path.Combine(appDataPath, "revit-scripts", "LogViewChanges", $"{selectedDoc.Title}");

            if (!File.Exists(logFilePath))
            {
                TaskDialog.Show("Error", "Log file does not exist for the selected project.");
                return Result.Failed;
            }

            var viewEntries = File.ReadAllLines(logFilePath)
                .Reverse()
                .Distinct()
                .ToList();

            // Extract the last view entry
            string lastEntry = viewEntries.FirstOrDefault();

            if (string.IsNullOrEmpty(lastEntry))
            {
                TaskDialog.Show("Error", "No view entries found in log file.");
                return Result.Failed;
            }

            var parts = lastEntry.Split(new[] { ' ' }, 2); // Split into two parts: ID and Title

            if (parts.Length != 2)
            {
                TaskDialog.Show("Error", "Invalid entry in log file.");
                return Result.Failed;
            }

            string viewIdString = parts[0];
            int viewIdInteger;
            if (!int.TryParse(viewIdString, out viewIdInteger))
            {
                TaskDialog.Show("Error", "Invalid view ID in log file.");
                return Result.Failed;
            }

            ElementId viewId = new ElementId(viewIdInteger);
            View viewToActivate = selectedDoc.GetElement(viewId) as View;

            if (viewToActivate == null)
            {
                TaskDialog.Show("Error", "View not found in the selected document.");
                return Result.Failed;
            }

            // Activate the view in the selected document
            selectedUIDoc.ActiveView = viewToActivate;

            return Result.Succeeded;
        }
        catch (Exception ex)
        {
            TaskDialog.Show("Error", "Failed to open and activate document:\n" + ex.Message);
            return Result.Failed;
        }
    }
