public void healthBar(float amount)
{
    // Calculate the original width of the health bar
    float originalWidth = Health.rectTransform.rect.width;

    // Decrease the health by the given amount
    health -= (int)amount;

    // Ensure health doesn't go below 0
    if (health < 0) 
    {
        health = 0;
    }

    // Calculate the health percentage relative to the starting health
    float healthPercentage = (float)health / 45f; // 45f is the starting health

    // Update the health bar width based on the health percentage
    Health.rectTransform.sizeDelta = new Vector2(originalWidth * healthPercentage, Health.rectTransform.sizeDelta.y);

    // If health is 0 or less, destroy the AI object (optional)
    if (health <= 0)
    {
        Destroy(gameObject);  // Destroy AI object on death
    }
}

