#include <iostream>
#include <vector>
#include <queue>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <functional>
#include <future>
#include <stop_token>

class ThreadPool {
public:
    explicit ThreadPool(size_t thread_count);
    ~ThreadPool();

    template<typename Func, typename... Args>
    auto submit(Func&& f, Args&&... args) -> std::future<std::invoke_result_t<Func, Args...>>;

private:
    std::vector<std::jthread> workers;
    std::queue<std::function<void()>> tasks;

    std::mutex queue_mutex;
    std::condition_variable_any condition;
};

ThreadPool::ThreadPool(size_t thread_count) {
    for (size_t i = 0; i < thread_count; ++i) {
        workers.emplace_back([this](std::stop_token stoken) {
            while (!stoken.stop_requested()) {
                std::function<void()> task;

                {
                    std::unique_lock lock(queue_mutex);
                    condition.wait(lock, stoken, [this] {
                        return !tasks.empty();
                    });

                    if (stoken.stop_requested())
                        break;

                    task = std::move(tasks.front());
                    tasks.pop();
                }

                task();
            }
        });
    }
}

ThreadPool::~ThreadPool() {
    for (auto& worker : workers)
        worker.request_stop();

    condition.notify_all();
}

template<typename Func, typename... Args>
auto ThreadPool::submit(Func&& f, Args&&... args) -> std::future<std::invoke_result_t<Func, Args...>> {
    using return_type = std::invoke_result_t<Func, Args...>;

    auto task = std::make_shared<std::packaged_task<return_type()>>(
        std::bind(std::forward<Func>(f), std::forward<Args>(args)...)
    );

    {
        std::lock_guard lock(queue_mutex);
        tasks.emplace([task]() { (*task)(); });
    }

    condition.notify_one();
    return task->get_future();
}

