// Set thread affinity to a specific core (Linux only)
void ThreadPool::set_affinity(size_t thread_index) {
#if defined(__linux__)
    cpu_set_t cpuset;
    CPU_ZERO(&cpuset);
    CPU_SET(thread_index % std::thread::hardware_concurrency(), &cpuset);

    pthread_t native_handle = pthread_self();
    int rc = pthread_setaffinity_np(native_handle, sizeof(cpu_set_t), &cpuset);
    if (rc != 0) {
        std::cerr << "Warning: Failed to set thread affinity for thread " << thread_index << '\n';
    }
#else
    // No-op on non-Linux platforms
    (void)thread_index;
#endif
}

ThreadPool::ThreadPool(size_t num_threads) {
    for (size_t i = 0; i < num_threads; ++i) {
        workers.emplace_back([this, i](std::stop_token stoken) {
            set_affinity(i);

            while (!stoken.stop_requested()) {
                std::packaged_task<void()> task;

                {
                    std::unique_lock lock(queue_mutex);
                    condition.wait(lock, stoken, [this] {
                        return !tasks.empty();
                    });

                    if (stoken.stop_requested()) break;

                    task = std::move(tasks.front());
                    tasks.pop();
                }

                try {
                    task();
                } catch (const std::exception& e) {
                    std::cerr << "Exception in task: " << e.what() << '\n';
                } catch (...) {
                    std::cerr << "Unknown exception in task\n";
                }
            }
        });
    }
}

ThreadPool::~ThreadPool() {
    for (auto& t : workers)
        t.request_stop();
    condition.notify_all();
}

template<typename Func, typename... Args>
auto ThreadPool::submit(Func&& f, Args&&... args)
    -> std::future<std::invoke_result_t<Func, Args...>> {

    using ReturnType = std::invoke_result_t<Func, Args...>;

    auto bound_task = [fwd_f = std::forward<Func>(f), ...fwd_args = std::forward<Args>(args)]() mutable -> ReturnType {
        return std::invoke(std::move(fwd_f), std::move(fwd_args)...);
    };

    auto task_wrapper = std::packaged_task<ReturnType()>(std::move(bound_task));
    auto future = task_wrapper.get_future();

    {
        std::lock_guard lock(queue_mutex);
        tasks.emplace([task = std::move(task_wrapper)]() mutable {
            task(); // may throw, caught in thread body
        });
    }

    condition.notify_one();
    return future;
}

