template<typename Func, typename... Args>
auto submit_cancellable_with_timeout(std::chrono::milliseconds timeout, Func&& f, Args&&... args)
    -> std::optional<std::invoke_result_t<Func, std::stop_token, Args...>> {

    using ReturnType = std::invoke_result_t<Func, std::stop_token, Args...>;

    std::promise<ReturnType> result_promise;
    auto result_future = result_promise.get_future();

    std::jthread::id task_thread_id;

    // Task wrapper that takes stop_token
    auto task = [p = std::move(result_promise), 
                 func = std::forward<Func>(f), 
                 ... args = std::forward<Args>(args)]
                (std::stop_token stoken) mutable {
        try {
            if constexpr (std::is_void_v<ReturnType>) {
                std::invoke(func, stoken, std::move(args)...);
                p.set_value();
            } else {
                p.set_value(std::invoke(func, stoken, std::move(args)...));
            }
        } catch (...) {
            try {
                p.set_exception(std::current_exception());
            } catch (...) {}
        }
    };

    std::jthread task_thread(std::move(task));

    // Timer thread that will cancel the task after timeout
    std::thread timer([timeout, stoken = task_thread.get_stop_token(), &task_thread]() mutable {
        std::this_thread::sleep_for(timeout);
        if (!stoken.stop_requested()) {
            task_thread.request_stop(); // cooperative stop
        }
    });

    timer.detach(); // don't block on the timer thread

    if (result_future.wait_for(timeout + std::chrono::milliseconds(50)) == std::future_status::ready) {
        return result_future.get();
    }

    return std::nullopt; // timed out
}

