template<typename Func, typename... Args>
auto ThreadPool::submit_cancellable_with_timeout(std::chrono::milliseconds timeout,
                                                  Func&& f, Args&&... args)
    -> std::optional<std::invoke_result_t<Func, std::stop_token, Args...>> {

    using ReturnType = std::invoke_result_t<Func, std::stop_token, Args...>;
    std::promise<ReturnType> prom;
    auto fut = prom.get_future();

    // Create a stop_source for this task
    auto stop_source = std::make_shared<std::stop_source>();

    auto task = [func = std::forward<Func>(f),
                 ...args = std::forward<Args>(args),
                 p = std::move(prom),
                 stop_source](std::stop_token pool_token) mutable {

        std::stop_token effective_token = stop_source->get_token();

        try {
            if constexpr (std::is_void_v<ReturnType>) {
                std::invoke(func, effective_token, std::move(args)...);
                p.set_value();
            } else {
                p.set_value(std::invoke(func, effective_token, std::move(args)...));
            }
        } catch (...) {
            try {
                p.set_exception(std::current_exception());
            } catch (...) {}
        }
    };

    {
        std::lock_guard lock(queue_mutex);
        tasks.emplace(std::move(task));
    }

    condition.notify_one();

    // Start a timer thread to cancel the task if needed
    std::thread([stop_source, timeout]() {
        std::this_thread::sleep_for(timeout);
        stop_source->request_stop();
    }).detach();

    if (fut.wait_for(timeout + std::chrono::milliseconds(50)) == std::future_status::ready) {
        return fut.get();
    } else {
        return std::nullopt;
    }
}

