#include <jthread>
#include <functional>
#include <future>
#include <optional>
#include <vector>
#include <chrono>
#include <iostream>
#include <thread>
#include "concurrentqueue.h" // moodycamel::ConcurrentQueue

class LockFreeThreadPool {
public:
    using Task = std::function<void(std::stop_token)>;

    explicit LockFreeThreadPool(size_t thread_count) {
        for (size_t i = 0; i < thread_count; ++i) {
            workers.emplace_back([this](std::stop_token stoken) {
                while (!stoken.stop_requested()) {
                    Task task;
                    if (tasks.try_dequeue(task)) {
                        try {
                            task(stoken);
                        } catch (const std::exception& e) {
                            std::cerr << "Task exception: " << e.what() << "\n";
                        } catch (...) {
                            std::cerr << "Unknown task exception\n";
                        }
                    } else {
                        std::this_thread::yield(); // lightweight fallback
                    }
                }
            });
        }
    }

    ~LockFreeThreadPool() {
        for (auto& t : workers) {
            t.request_stop();
        }
    }

    // Simple submit (non-cancellable)
    template<typename Func, typename... Args>
    auto submit(Func&& f, Args&&... args)
        -> std::future<std::invoke_result_t<Func, Args...>> {

        using RetType = std::invoke_result_t<Func, Args...>;
        std::promise<RetType> prom;
        auto fut = prom.get_future();

        auto bound = [func = std::forward<Func>(f), ...args = std::forward<Args>(args)]() mutable {
            return std::invoke(func, std::move(args)...);
        };

        tasks.enqueue([task = std::move(bound), p = std::move(prom)](std::stop_token) mutable {
            try {
                if constexpr (std::is_void_v<RetType>) {
                    task();
                    p.set_value();
                } else {
                    p.set_value(task());
                }
            } catch (...) {
                p.set_exception(std::current_exception());
            }
        });

        return fut;
    }

    // Cancellable submit with timeout
    template<typename Func, typename... Args>
    auto submit_cancellable_with_timeout(std::chrono::milliseconds timeout,
                                         Func&& f, Args&&... args)
        -> std::optional<std::invoke_result_t<Func, std::stop_token, Args...>> {

        using RetType = std::invoke_result_t<Func, std::stop_token, Args...>;
        std::promise<RetType> prom;
        auto fut = prom.get_future();
        auto stop_source = std::make_shared<std::stop_source>();

        tasks.enqueue([func = std::forward<Func>(f),
                       ... args = std::forward<Args>(args),
                       p = std::move(prom),
                       stop_source](std::stop_token) mutable {
            auto st = stop_source->get_token();
            try {
                if constexpr (std::is_void_v<RetType>) {
                    std::invoke(func, st, std::move(args)...);
                    p.set_value();
                } else {
                    p.set_value(std::invoke(func, st, std::move(args)...));
                }
            } catch (...) {
                p.set_exception(std::current_exception());
            }
        });

        // Start timeout thread
        std::thread([timeout, stop_source]() {
            std::this_thread::sleep_for(timeout);
            stop_source->request_stop();
        }).detach();

        if (fut.wait_for(timeout + std::chrono::milliseconds(50)) == std::future_status::ready) {
            return fut.get();
        } else {
            return std::nullopt;
        }
    }

private:
    std::vector<std::jthread> workers;
    moodycamel::ConcurrentQueue<Task> tasks;
};

C++
int main() {
    LockFreeThreadPool pool(4);

    auto result = pool.submit_cancellable_with_timeout(
        std::chrono::seconds(2),
        [](std::stop_token stoken, int x) -> int {
            for (int i = 0; i < 10; ++i) {
                if (stoken.stop_requested()) {
                    std::cout << "Cancelled task!\n";
                    return -1;
                }
                std::this_thread::sleep_for(std::chrono::milliseconds(500));
            }
            return x * x;
        }, 7);

    if (result) {
        std::cout << "Task result: " << *result << "\n";
    } else {
        std::cout << "Task timed out\n";
    }
}

