# Create a lexer using HOP::Lexer
my $lexer = string_lexer($input,
    [ 'LPAREN',        qr/\(/ ],
    [ 'RPAREN',        qr/\)/ ],
    [ 'QUOTED_STRING', qr/'[^']*'|"[^"]*"/ ],
    [ 'IDENTIFIER',    qr/[^()\s]+/ ],
    [ 'WHITESPACE',    qr/\s+/, sub {} ],  # Skip whitespace
);

# Parse s-expressions recursively
sub parse_sexp {
    my ($lexer) = @_;
    my $token = $lexer->();
    return unless $token;
    my ($type, $value) = @$token;

    if ($type eq 'LPAREN') {
        my @list;
        while (1) {
            my $next_token = $lexer->('peek');
            last unless $next_token;
            my ($next_type) = @$next_token;
