// main.js
document.addEventListener('DOMContentLoaded', function () {
  const triggers = document.querySelectorAll('[data-modal-target]');
  const modals = document.querySelectorAll('.modal');
  let lastTrigger = null;

  function setAria(modal, isOpen) {
    modal.setAttribute('aria-hidden', isOpen ? 'false' : 'true');
  }

  function focusTrap(modal, e) {
    if (e.key !== 'Tab') return;
    const focusables = modal.querySelectorAll(
      'a, button, input, textarea, select, details,[tabindex]:not([tabindex="-1"])'
    );
    if (!focusables.length) return;

    const first = focusables[0];
    const last = focusables[focusables.length - 1];

    if (e.shiftKey && document.activeElement === first) {
      e.preventDefault();
      last.focus();
    } else if (!e.shiftKey && document.activeElement === last) {
      e.preventDefault();
      first.focus();
    }
  }

  function onBackdrop(e) {
    // Close if clicked on backdrop or element with data-modal-close
    if (e.target.hasAttribute('data-modal-close') || e.target.classList.contains('modal')) {
      closeModal(e.currentTarget);
    }
  }

  function onEsc(e) {
    if (e.key === 'Escape') {
      const open = document.querySelector('.modal.is-open');
      if (open) closeModal(open);
    }
  }

  function openModal(id, trigger) {
    const modal = document.getElementById(id);
    if (!modal) return;

    modal.classList.add('is-open');
    document.body.classList.add('modal-open');
    setAria(modal, true);
    lastTrigger = trigger || null;

    // Focus the dialog container
    const dialog = modal.querySelector('.modal__dialog');
    if (dialog) dialog.focus();

    // Attach listeners
    modal.addEventListener('click', onBackdrop);
    document.addEventListener('keydown', onEsc);

    // Create & store a bound focus-trap handler so we can remove it later
    const trapHandler = (e) => focusTrap(modal, e);
    document.addEventListener('keydown', trapHandler, { capture: true });
    // store reference on the modal for cleanup
    modal._trapHandler = trapHandler;
  }

  function closeModal(modal) {
    modal.classList.remove('is-open');
    document.body.classList.remove('modal-open');
    setAria(modal, false);

    // Detach listeners
    modal.removeEventListener('click', onBackdrop);
    document.removeEventListener('keydown', onEsc);

    // Remove the specific focus-trap handler for this modal
    if (modal._trapHandler) {
      document.removeEventListener('keydown', modal._trapHandler, { capture: true });
      delete modal._trapHandler;
    }

    // Restore focus to the trigger
    if (lastTrigger) {
      lastTrigger.focus();
      lastTrigger = null;
    }
  }

  // Open handlers for each card trigger
  triggers.forEach((el) => {
    el.addEventListener('click', () => openModal(el.getAttribute('data-modal-target'), el));
    el.addEventListener('keydown', (e) => {
      if (e.key === 'Enter' || e.key === ' ') {
        e.preventDefault();
        openModal(el.getAttribute('data-modal-target'), el);
      }
    });
  });

  // Close buttons inside each modal
  modals.forEach((m) => {
    m.querySelectorAll('[data-modal-close]').forEach((btn) => {
      btn.addEventListener('click', () => closeModal(m));
    });
  });
});

