function initializeVideo(video) {
    const canvas = document.getElementById('canvas');
    const ctx = canvas.getContext('2d');
    const frameRate = 30; // Replace with your video's frame rate
    const frameTime = 1 / frameRate;
    let currentFrame = 0;

    video.currentTime = 0;
    video.addEventListener('seeked', () => {
        ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
    });

    document.getElementById('next-frame').addEventListener('click', () => {
        currentFrame++;
        video.currentTime = currentFrame * frameTime;
    });

    document.getElementById('prev-frame').addEventListener('click', () => {
        currentFrame = Math.max(0, currentFrame - 1);
        video.currentTime = currentFrame * frameTime;
    });

    video.addEventListener('loadeddata', () => {
        canvas.width = video.videoWidth;
        canvas.height = video.videoHeight;
        ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
    });
}

