            val entity = response.entity
            val jsonResponse = JsonParser.parseReader(InputStreamReader(entity.content)).asJsonObject
            EntityUtils.consume(entity)
            return jsonResponse["access_token"]?.asString
        }
    }

    override fun handle(ctx: CommandContext, requestingUserDto: UserDto, deleteDelay: Int?) {
        try {
            HttpClients.createDefault().use { httpClient ->
                val accessToken = getAccessToken(httpClient)
                if (accessToken != null) {
                    handle(ctx, httpClient, accessToken, requestingUserDto, deleteDelay)
                } else {
                    logger.error("Failed to get Reddit access token")
                    throw RuntimeException("Failed to get Reddit access token")
                }
            }
        } catch (e: IOException) {
            logger.error("IOException occurred while handling command", e)
            throw RuntimeException(e)
        }
    }

    @Throws(IOException::class)
    fun handle(ctx: CommandContext, httpClient: CloseableHttpClient, accessToken: String, requestingUserDto: UserDto?, deleteDelay: Int?) {
        val event = ctx.event
        event.deferReply().queue()

        if (requestingUserDto?.memePermission != true) {
            logger.info("User does not have meme permission: ${requestingUserDto?.username}")
            sendErrorMessage(event, deleteDelay ?: 0)
            return
        }

        val result = getRedditApiArgs(event)
        val subredditArg = result.subredditArg

        if (subredditArg == "sneakybackgroundfeet") {
            logger.info("User requested subreddit 'sneakybackgroundfeet'")
            event.hook.sendMessageFormat("Don't talk to me.").queue(invokeDeleteOnMessageResponse(deleteDelay ?: 0))
        } else {
            val embed = fetchRedditPost(result, event, deleteDelay ?: 0, httpClient, accessToken)
            if (embed != null) {
                logger.info("Successfully fetched meme from subreddit: $subredditArg")
                event.hook.sendMessageEmbeds(embed).queue()
            } else {
                logger.warn("Failed to fetch meme from subreddit: $subredditArg")
                event.hook.sendMessage("Failed to fetch meme. Please try again later.").queue(invokeDeleteOnMessageResponse(deleteDelay ?: 0))
            }
        }
    }

    private fun getRedditApiArgs(event: SlashCommandInteractionEvent): RedditApiArgs {
        val subredditArg = event.getOption(SUBREDDIT)?.asString
        val timePeriod = TimePeriod.parseTimePeriod(event.getOption(TIME_PERIOD)?.asString ?: "day").timePeriod
        val limit = event.getOption(LIMIT)?.asInt ?: 5
        logger.debug("Reddit API args - Subreddit: $subredditArg, Time Period: $timePeriod, Limit: $limit")
        return RedditApiArgs(subredditArg, timePeriod, limit)
    }

    @Throws(IOException::class)
    private fun fetchRedditPost(result: RedditApiArgs, event: SlashCommandInteractionEvent, deleteDelay: Int, httpClient: HttpClient, accessToken: String): MessageEmbed? {
        val gson = Gson()
        val redditApiUrl = String.format(RedditAPIDto.redditPrefix, result.subredditArg, result.limit, result.timePeriod)
        val request = HttpGet(redditApiUrl).apply {
            setHeader("Authorization", "Bearer $accessToken")
            setHeader("User-Agent", "YourAppName/0.1 by YourRedditUsername")
        }
        logger.info("Fetching Reddit post from URL: $redditApiUrl")
        val response = httpClient.execute(request)

        return response.also { // Using `also` to perform additional operations on the response object
            if (response.statusLine.statusCode == 200) {
                val jsonResponse = JsonParser.parseReader(InputStreamReader(response.entity.content)).asJsonObject
                EntityUtils.consume(response.entity) // Ensure the entity content is fully consumed

                val children = jsonResponse.getAsJsonObject("data").getAsJsonArray("children")

                if (children.size() == 0) {
                    logger.info("No memes found in subreddit: ${result.subredditArg}")
                    event.hook.sendMessageFormat("No memes found in the subreddit.").queue(invokeDeleteOnMessageResponse(deleteDelay))
                    return@also null
                }

                val meme = children[Random.nextInt(children.size())].asJsonObject.getAsJsonObject("data")
                val redditAPIDto = gson.fromJson(meme.toString(), RedditAPIDto::class.java)

                if (redditAPIDto.isNsfw == true) {
                    logger.warn("NSFW meme detected from subreddit: ${result.subredditArg}")
                    event.hook.sendMessageFormat("I received a NSFW subreddit from %s, or reddit gave me a NSFW meme, either way somebody shoot that guy", event.member).queue(invokeDeleteOnMessageResponse(deleteDelay))
                    return@also null
                } else if (redditAPIDto.video == true) {
                    logger.warn("Video meme detected from subreddit: ${result.subredditArg}")
                    event.hook.sendMessageFormat("I pulled back a video, whoops. Try again maybe? Or not, up to you.").queue(invokeDeleteOnMessageResponse(deleteDelay))
                    return@also null
                }

                val title = meme["title"].asString
                val url = meme["url"].asString
                val author = meme["author"].asString

                logger.info("Meme fetched successfully - Title: $title, Author: $author, URL: $url")

                return EmbedBuilder().apply {
                    setTitle(title, url)
                    setAuthor(author, null, null)
                    setImage(url)
                    addField("subreddit", result.subredditArg ?: "unknown", false)
                }.build()
            } else {
                logger.error("Error response from Reddit API: ${response.statusLine.statusCode}")
                null
            }
        }
    }

    private data class RedditApiArgs(val subredditArg: String?, val timePeriod: String, val limit: Int)

    private fun sendErrorMessage(event: SlashCommandInteractionEvent, deleteDelay: Int) {
        event.hook.sendMessageFormat("Sorry, you do not have permission to request memes").queue(invokeDeleteOnMessageResponse(deleteDelay))
    }

    override fun getName(): String {
        return "meme"
    }

    override fun getDescription(): String {
        return "Get a meme from a specified subreddit"
    }

    override fun getOptions(): List<OptionData> {
        return listOf(
            OptionData(OptionType.STRING, SUBREDDIT, "The subreddit to get the meme from").setRequired(true),
            OptionData(OptionType.STRING, TIME_PERIOD, "The time period to get the meme from").setRequired(false).addChoice("day", "day").addChoice("week", "week").addChoice("month", "month").addChoice("year", "year").addChoice("all", "all"),
            OptionData(OptionType.INTEGER, LIMIT, "The number of memes to fetch").setRequired(false)
        )
    }
}

