int
lws_ring_insert(struct lws_ring *ring, const void *src, size_t count)
{
    size_t i;
    int first = 1;

    /* Ensure thread safety */
    pthread_mutex_lock(&ring->lock);

    /* Insert elements */
    for (i = 0; i < count; i++) {
        ring->buf[ring->head] = src;
        ring->head = (ring->head + 1) & (ring->buf_size - 1);
        if (ring->head == ring->tail && !first) {
            ring->tail = (ring->tail + 1) & (ring->buf_size - 1);
        }
        first = 0;
    }

    pthread_mutex_unlock(&ring->lock);
    return 0;
}

C
void
lws_sul_schedule(struct lws_context *context, int tsi,
                 lws_sorted_usec_list_t *sul, sul_cb_t cb, lws_usec_t us)
{
    /* Ensure this function can be safely called from any thread */
    pthread_mutex_lock(&context->sul_lock);

    /* Add to sorted list */
    sul->cb = cb;
    sul->us = us + lws_now_usecs();
    sul->context = context;
    lws_add_sul(sul);

    pthread_mutex_unlock(&context->sul_lock);
}

