"""
We want to write a program that consists of
1. The Wumpus World
2. A Player / Agent that has limited visibility of the world but can collect percepts
and perform logic inference.

"""

class World:
    """
    The Wumpus World.
    """
    def __init__(self):
        """
        Initialize the state of the game, where the Wumpus is, where the pits are, etc.
        Represent the entities in the world,
        - Maybe 2d array to represent the grid?
        """
        self.facts = set()

    def ask(self, sentence):
        """
        Return whether the given sentence input is true in the World.
        For example, we want to be able to ask, W[1,1]? Then return False if no wumpus.
        """
        if isinstance(sentence, str):
            return sentence in self.facts

        operator, *operands = sentence

        if operator == 'NOT':
            return not self.ask(operands[0])
        elif operator == 'AND':
            return all(self.ask(op) for op in operands)
        elif operator == 'OR':
            return sentence in self.facts or any(self.ask(op) for op in operands)
        elif operator == 'IMPLIES':
            # p => q means either not p or q
            return not self.ask(operands[0]) or self.ask(operands[1])
        elif operator == 'IFF':
            return self.ask(operands[0]) == self.ask(operands[1])

    def tell(self, sentence):
        """
        Give the world a sentence and tell it that this sentence is true.
        """
        self.facts.add(sentence)

def to_cnf(sentence):
    """
    Converts a given sentence to Conjunctive Normal Form (CNF).
    """
    if isinstance(sentence, str):
        return sentence  # Simple literals like 'P', 'Q'

    operator, *operands = sentence

    # Handle NOT first
    if operator == 'NOT':
        subformula = operands[0]
        if isinstance(subformula, tuple):
            sub_op, *sub_operands = subformula
            if sub_op == 'AND':
                # De Morgan's law: NOT (P AND Q) becomes (NOT P) OR (NOT Q)
                return ('OR', to_cnf(('NOT', sub_operands[0])), to_cnf(('NOT', sub_operands[1])))
            elif sub_op == 'OR':
                # De Morgan's law: NOT (P OR Q) becomes (NOT P) AND (NOT Q)
                return ('AND', to_cnf(('NOT', sub_operands[0])), to_cnf(('NOT', sub_operands[1])))
        return sentence  # 'NOT' applied to an atomic proposition

    # IMPLIES: (P IMPLIES Q) becomes (NOT P OR Q)
    elif operator == 'IMPLIES':
        return to_cnf(('OR', ('NOT', operands[0]), operands[1]))

    # IFF: (P IFF Q) becomes (P => Q) AND (Q => P)
    elif operator == 'IFF':
        p, q = operands
        return to_cnf(('AND', ('IMPLIES', p, q), ('IMPLIES', q, p)))

    # AND: Keep AND as it is
    elif operator == 'AND':
        return ('AND', to_cnf(operands[0]), to_cnf(operands[1]))

    # OR: Keep OR as it is
    elif operator == 'OR':
        return ('OR', to_cnf(operands[0]), to_cnf(operands[1]))

    return sentence  # Catch-all for literals or unknown structures

def resolve(ci, cj):
    """
    Takes two clauses in CNF and resolves them to produce resolvents.
    """
    if isinstance(ci, str):
        ci = {ci}
    if isinstance(cj, str):
        cj = {cj}
    ci = set(ci)
    cj = set(cj)
    resolvents = set()

    for di in ci:
