                resolvents.add(frozenset(resolvent))
            elif isinstance(dj, tuple) and dj[0] == 'NOT' and dj[1] == di:
                resolvent = ci.union(cj) - {di, dj}
                resolvents.add(frozenset(resolvent))

    return resolvents if resolvents else set()

class Player:
    """
