# Track the state of the Caps Lock key
caps_lock_pressed = False

def on_press(key):
    global caps_lock_pressed
    try:
        if key == keyboard.Key.caps_lock:
            if not caps_lock_pressed:
                print("Caps Lock pressed")
                caps_lock_pressed = True
    except AttributeError:
        pass

def on_release(key):
    global caps_lock_pressed
    try:
        if key == keyboard.Key.caps_lock:
            if caps_lock_pressed:
                print("Caps Lock released")
                caps_lock_pressed = False
    except AttributeError:
        pass

