function throttle(func, wait, options = {}) {
  let lastCall = 0;
  let timeoutId = null;
  let lastArgs = null;
  let lastContext = null;

  const { leading = true, trailing = true } = options;

  const invokeFunc = (time) => {
    lastCall = time;
    func.apply(lastContext, lastArgs);
    lastArgs = lastContext = null;
  };

  const throttled = function(...args) {
    const now = Date.now();
    const isInvoking = leading && lastCall === 0;

    lastArgs = args;
    lastContext = this;

    if (isInvoking) {
      invokeFunc(now);
    }

    const remainingTime = wait - (now - lastCall);

    if (remainingTime <= 0 || remainingTime > wait) {
      if (timeoutId) {
        clearTimeout(timeoutId);
        timeoutId = null;
      }
      invokeFunc(now);
    } else if (!timeoutId && trailing) {
      timeoutId = setTimeout(() => {
        timeoutId = null;
        if (trailing && lastArgs) {
          invokeFunc(Date.now());
        }
      }, remainingTime);
    }
  };

  throttled.cancel = () => {
    clearTimeout(timeoutId);
    timeoutId = lastArgs = lastContext = null;
    lastCall = 0;
  };

  throttled.flush = () => {
    if (timeoutId) {
      clearTimeout(timeoutId);
      timeoutId = null;
      invokeFunc(Date.now());
    }
  };

  return throttled;
}

