function throttle(func, wait) {
  let lastCall = 0;
  let timeoutId = null;
  let lastArgs = null;
  let lastContext = null;
  let pendingPromise = null;

  const invokeFunc = async (time) => {
    lastCall = time;
    const result = func.apply(lastContext, lastArgs);
    lastArgs = lastContext = null;
    pendingPromise = result instanceof Promise ? result : Promise.resolve(result);
    await pendingPromise;
  };

  const throttled = function(...args) {
    const now = Date.now();
    lastArgs = args;
    lastContext = this;

    const isLeadingCall = lastCall === 0;

    if (isLeadingCall) {
      invokeFunc(now);
    }

    const remainingTime = wait - (now - lastCall);

    if (remainingTime <= 0 || remainingTime > wait) {
      if (timeoutId) {
        clearTimeout(timeoutId);
        timeoutId = null;
      }
      invokeFunc(now);
    } else if (!timeoutId) {
      timeoutId = setTimeout(() => {
        timeoutId = null;
        invokeFunc(Date.now());
      }, remainingTime);
    }

    return pendingPromise;
  };

  return throttled;
}

