export default class PrintButtonApplicationCustomizer extends BaseApplicationCustomizer<IPrintButtonApplicationCustomizerProperties> {

  @override
  public async onInit(): Promise<void> {
    Log.info(LOG_SOURCE, `Initialized PrintButtonApplicationCustomizer`);

    // Ensure PnP is properly initialized
    sp.setup({
      spfxContext: this.context
    });

    // Add the right vertical section and button on a sample page
    await this.addRightSectionAndButtonToPage("SitePages/Home.aspx");

    return Promise.resolve();
  }

  private async addRightSectionAndButtonToPage(pageUrl: string): Promise<void> {
    try {
      // Load the SharePoint page
      const page: IClientSidePage = await sp.web.loadClientsidePage(pageUrl);

      // Check if the page already has a vertical section
      const hasVerticalSection = page.sections.some(section => section.layoutIndex === 2);

      if (!hasVerticalSection) {
        // Add a vertical section (index 2 is for the right vertical section)
        page.addSection(2);
      }

      // Add a text part with the button HTML to the vertical section
      const buttonHtml = `<button style="padding: 10px; background-color: #0078d4; color: white; border: none; border-radius: 5px; cursor: pointer;" onclick="window.print()">Print or Save as PDF</button>`;
      const buttonWebpart = ClientsideText(buttonHtml);

      // Find the vertical section and add the button web part
      const verticalSection = page.sections.find(section => section.layoutIndex === 2);
      if (verticalSection) {
        verticalSection.addControl(buttonWebpart);
        await page.save();
        Log.info(LOG_SOURCE, `Button added to vertical section on page ${pageUrl}`);
      }
    } catch (error) {
      Log.error(LOG_SOURCE, error.message);
    }
  }
}

