import (
    "sync"
)

// Eviction status map
var evictionStatusMap = struct {
    sync.RWMutex
    status map[string]float64 // Key: "namespace/podName", Value: 1 (normal) or 0 (evicted)
}{status: make(map[string]float64)}

func updateEvictionStatus(podName, namespace string, value float64) {
    key := namespace + "/" + podName
    evictionStatusMap.Lock()
    evictionStatusMap.status[key] = value
    evictionStatusMap.Unlock()
}

func getEvictionStatus(podName, namespace string) float64 {
    key := namespace + "/" + podName
    evictionStatusMap.RLock()
    defer evictionStatusMap.RUnlock()
    return evictionStatusMap.status[key]
}

