func serveMetrics(w http.ResponseWriter, r *http.Request) {
    // Extract namespace and pod name from the request
    namespace := r.URL.Query().Get("namespace")
    podName := r.URL.Query().Get("podName")

    // Get eviction status
    value := getEvictionStatus(podName, namespace)

    // Create response
    metric := metricsv1beta1.MetricValue{
        DescribedObject: metricsv1beta1.ObjectReference{
            Kind:      "Pod",
            Namespace: namespace,
            Name:      podName,
        },
        Value: *resource.NewQuantity(int64(value), resource.DecimalSI),
        Timestamp: metav1.Now(),
    }
    response := metricsv1beta1.MetricValueList{
        Items: []metricsv1beta1.MetricValue{metric},
    }

    // Respond with the metric
    json.NewEncoder(w).Encode(response)
}

func main() {
    http.HandleFunc("/metrics", serveMetrics)
    http.ListenAndServe(":8080", nil)
