const fs = require('fs');
const path = require('path');
const doctrine = require('doctrine'); // Parses JSDoc comments

// Path to your source code and output directory
const COMPONENTS_DIR = './src/components';
const OUTPUT_DIR = './docs/examples';

// Ensure the output directory exists
if (!fs.existsSync(OUTPUT_DIR)) {
  fs.mkdirSync(OUTPUT_DIR, { recursive: true });
}

// Parse JSDoc comments from a file
function parseJSDoc(fileContent) {
  const comments = [];
  const regex = /\/\*\*([\s\S]*?)\*\//g;
  let match;

  while ((match = regex.exec(fileContent)) !== null) {
    comments.push(match[1]);
  }

  return comments.map((comment) => doctrine.parse(comment, { unwrap: true }));
}

// Extract examples and generate Markdown files
function extractExamples(filePath) {
  const fileContent = fs.readFileSync(filePath, 'utf-8');
  const jsdocComments = parseJSDoc(fileContent);

  jsdocComments.forEach((comment, index) => {
    const exampleTags = comment.tags.filter((tag) => tag.title === 'example');
    if (exampleTags.length > 0) {
      exampleTags.forEach((tag, idx) => {
        const exampleContent = tag.description.trim();
        const componentName = path.basename(filePath, path.extname(filePath));
        const outputFileName = `${componentName}-example-${index + 1}.md`;

        // Write the example to a Markdown file
        fs.writeFileSync(
          path.join(OUTPUT_DIR, outputFileName),
          `# Example for ${componentName}\n\n\`\`\`tsx\n${exampleContent}\n\`\`\`\n`
        );

        console.log(`✅ Example extracted to: ${outputFileName}`);
      });
    }
  });
}

// Process all files in the components directory
function processComponents(dir) {
  const files = fs.readdirSync(dir);

  files.forEach((file) => {
    const filePath = path.join(dir, file);
    const stats = fs.statSync(filePath);

    if (stats.isDirectory()) {
      processComponents(filePath); // Recursively process subdirectories
    } else if (file.endsWith('.tsx')) {
      extractExamples(filePath);
    }
  });
}

// Start the process
console.log('🔍 Extracting JSDoc examples...');
processComponents(COMPONENTS_DIR);
console.log('🎉 Examples extraction complete!');

