import asyncio

class Example:
    def __init__(self):
        self._nodes = [self]
        self.sub_chan_tasks = []

    async def handle(self, msg):
        if msg.get("error"):
            raise ValueError("An error occurred in handle!")
        return "Processed: " + str(msg)

    def _callback(self, fut, context):
        try:
            result = fut.result()  # This will raise if an exception occurred
            print("Callback result:", result)
        except Exception as e:
            print(f"Callback caught exception: {e}, Context: {context}")
        finally:
            if fut in self.sub_chan_tasks:
                self.sub_chan_tasks.remove(fut)

    async def submain(self, msg, ctx):
        fut = asyncio.create_task(self._nodes[0].handle(msg.copy()))
        fut.add_done_callback(lambda f: self._callback(f, context=ctx))
        self.sub_chan_tasks.append(fut)

    async def main(self):
        msg = {"error": True}  # Simulate an error
        ctx = {"info": "context information"}
        await self.submain(msg, ctx)

        # Await tasks and handle any exceptions gracefully
        try:
            subchan_fut = await asyncio.gather(*self.sub_chan_tasks)
            print("All tasks completed successfully:", subchan_fut)
        except Exception as e:
            print(f"Exception in gather: {e}")

# Run the example
example = Example()
asyncio.run(example.main())

