import asyncio

async def example_task(should_fail):
    if should_fail:
        raise ValueError("Task failed!")
    return "Task succeeded"

def my_callback(fut):
    try:
        print("Callback result:", fut.result())
    except Exception as e:
        print("Callback caught exception:", e)

async def main():
    tasks = [
        asyncio.create_task(example_task(True)),
        asyncio.create_task(example_task(False))
    ]

    # Attach callbacks to tasks
    for task in tasks:
        task.add_done_callback(my_callback)

    try:
        # Await all tasks with gather
        results = await asyncio.gather(*tasks)
        print("Gather results:", results)
    except Exception as e:
        print("Gather caught exception:", e)

asyncio.run(main())

