import re
from collections import deque

def restore_stress_marks(original: str, verbalized: str) -> str:
    def tokenize(text):
        # Words with apostrophes, or punctuation
        return re.findall(r"\w+(?:'\w+)?|[^\w\s]", text, re.UNICODE)

    def detokenize(tokens):
        text = ""
        for i, token in enumerate(tokens):
            if i > 0 and re.match(r"\w", token) and re.match(r"\w", tokens[i-1]):
                text += " "
            text += token
        return text

    # Tokenize both
    original_tokens = tokenize(original)
    verbalized_tokens = tokenize(verbalized)

    # Extract de-stressed versions from original tokens
    stress_queue = deque()
    for token in original_tokens:
        if re.match(r"\w", token):  # only words
            stress_queue.append((token.replace("`", ""), token))

    result = []
    for v_token in verbalized_tokens:
        if re.match(r"\w", v_token):  # a word
            v_base = v_token.replace("`", "")
            # Search stress_queue until match
            found = False
            while stress_queue:
                orig_base, orig_token = stress_queue.popleft()
                if orig_base == v_base:
                    result.append(orig_token)  # restore stressed version
                    found = True
                    break
            if not found:
                result.append(v_token)
        else:
            result.append(v_token)  # punctuation as is

    return detokenize(result)

