from _pytest.config import Config as PytestConfig

class BaseConfiguration(Configuration, LoggerMixin, ImmutableMixin):
    ...

    def apply_overrides(self, parser: configparser.ConfigParser, overrides: dict[str, dict[str, str]]) -> None:
        for section, keys in overrides.items():
            if not parser.has_section(section):
                parser.add_section(section)
            for key, value in keys.items():
                parser.set(section, key, value)

    @final
    @cached_property
    def parser(self) -> configparser.ConfigParser:
        """
        Parser that reads this configuration and merges CLI overrides if available.
        """
        self.log.debug(f"reading configuration from {self._path}")
        parser = configparser.ConfigParser()
        config_files = parser.read(self._path)
        self.log.debug(f"successfully read {config_files}")

        # Check if pytest config is available
        try:
            import pytest
            from _pytest.config import Config as PytestConfig
            config: PytestConfig = pytest.config  # only available in session
            raw_overrides = config.getoption("--config") or []
            overrides = parse_overrides(raw_overrides)
            self.apply_overrides(parser, overrides)
            self.log.debug(f"applied config overrides: {overrides}")
        except Exception as e:
            self.log.debug(f"no pytest overrides applied: {e}")

        return parser

