void split_channels() {
    // Open input file and get the tree
    TFile *fin = TFile::Open("input.root");
    TTree *tin = (TTree*)fin->Get("tree");

    // Input branch (fixed-size array)
    static float Waves[32][1024];
    tin->SetBranchAddress("Waves", &Waves);

    // Create output file and tree
    TFile *fout = TFile::Open("output.root", "RECREATE");
    TTree *tout = new TTree("tree", "tree with per-channel branches");

    // One buffer per channel
    static float Wave_channel[32][1024];
    for (int ch = 0; ch < 32; ++ch) {
        TString name = TString::Format("Wave%d", ch);
        tout->Branch(name, Wave_channel[ch], "Wave[1024]/F");
    }

    // Loop and fill
    Long64_t nentries = tin->GetEntries();
    for (Long64_t i = 0; i < nentries; ++i) {
        tin->GetEntry(i);
        for (int ch = 0; ch < 32; ++ch) {
            memcpy(Wave_channel[ch], Waves[ch], 1024 * sizeof(float));
        }
        tout->Fill();
    }

    fout->Write();
    fout->Close();
    fin->Close();
}

