<?php

namespace App\Models;

use Carbon\Carbon;
use Illuminate\Contracts\Auth\MustVerifyEmail;
use Illuminate\Database\Eloquent\Factories\HasFactory;
use Illuminate\Foundation\Auth\User as Authenticatable;
use Illuminate\Notifications\Notifiable;
use Illuminate\Database\Eloquent\SoftDeletes;

/**
 * Class User
 *
 * Roles:
 *  - PLAYER
 *  - PARENT
 *  - EVALUATOR
 *  - ADMIN
 *
 * Fields assumed: id, name, email, password, role, date_of_birth (nullable), parent_id (nullable), phone, etc.
 */
class User extends Authenticatable
{
    use HasFactory, Notifiable, SoftDeletes;

    const ROLE_PLAYER = 'player';
    const ROLE_PARENT = 'parent';
    const ROLE_EVALUATOR = 'evaluator';
    const ROLE_ADMIN = 'admin';

    protected $fillable = [
        'name',
        'email',
        'password',
        'role',
        'date_of_birth',
        'parent_id',
        'phone',
        'meta',
    ];

    protected $casts = [
        'date_of_birth' => 'date',
        'meta' => 'array',
    ];

    protected $hidden = [
        'password',
    ];

    /* --------------------
     | Relationships
     --------------------*/
    public function parent()
    {
        return $this->belongsTo(User::class, 'parent_id');
    }

    public function children()
    {
        return $this->hasMany(User::class, 'parent_id');
    }

    public function submissions()
    {
        return $this->hasMany(Submission::class, 'player_id');
    }

    public function assignedEvaluations()
    {
        return $this->hasMany(EvaluatorAssignment::class, 'evaluator_id');
    }

    public function paymentRequests()
    {
        return $this->hasMany(PaymentRequest::class, 'payer_id');
    }

    public function paymentTransactions()
    {
        return $this->hasMany(PaymentTransaction::class, 'payer_id');
    }

    /* --------------------
     | Helpers
     --------------------*/
    /**
     * Check if user is adult (>= 18). If date_of_birth missing, returns false.
     */
    public function isAdult(int $adultAge = 18): bool
    {
        if (!$this->date_of_birth) {
            return false;
        }

        return $this->date_of_birth->diffInYears(now()) >= $adultAge;
    }

    public function isPlayer(): bool
    {
        return $this->role === self::ROLE_PLAYER;
    }

    public function isParent(): bool
    {
        return $this->role === self::ROLE_PARENT;
    }

    public function isEvaluator(): bool
    {
        return $this->role === self::ROLE_EVALUATOR;
    }

    public function isAdmin(): bool
    {
        return $this->role === self::ROLE_ADMIN;
    }
}

