<?php

namespace App\Models;

use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Factories\HasFactory;
use Illuminate\Database\Eloquent\SoftDeletes;

/**
 * Tracks a payment request for a player.
 *
 * Fields: id, payer_id (player), parent_id (nullable), in_app_purchase_id, amount_cents, currency,
 * status, retry_count, notes, meta, created_at, updated_at
 *
 * Status flow:
 *  - pending (default) // if player is minor, waiting for parent approval
 *  - parent_approved
 *  - parent_rejected
 *  - payment_initiated
 *  - paid
 *  - failed
 */
class PaymentRequest extends Model
{
    use HasFactory, SoftDeletes;

    const STATUS_PENDING = 'pending';
    const STATUS_PARENT_APPROVED = 'parent_approved';
    const STATUS_PARENT_REJECTED = 'parent_rejected';
    const STATUS_PAYMENT_INITIATED = 'payment_initiated';
    const STATUS_PAID = 'paid';
    const STATUS_FAILED = 'failed';

    protected $fillable = [
        'payer_id',
        'parent_id',
        'in_app_purchase_id',
        'amount_cents',
        'currency',
        'status',
        'retry_count',
        'notes',
        'meta',
    ];

    protected $casts = [
        'meta' => 'array',
        'amount_cents' => 'integer',
    ];

    protected $attributes = [
        'retry_count' => 0,
        'status' => self::STATUS_PENDING,
        'currency' => 'USD',
    ];

    /* --------------------
     | Relationships
     --------------------*/
    public function payer()
    {
        return $this->belongsTo(User::class, 'payer_id');
    }

    public function parent()
    {
        return $this->belongsTo(User::class, 'parent_id');
    }

    public function inAppPurchase()
    {
        return $this->belongsTo(InAppPurchase::class, 'in_app_purchase_id');
    }

    public function paymentTransaction()
    {
        return $this->hasOne(PaymentTransaction::class, 'payment_request_id');
    }

    /* --------------------
     | Scopes
     --------------------*/
    public function scopePending($q)
    {
        return $q->where('status', self::STATUS_PENDING);
    }

    public function scopeAwaitingParent($q)
    {
        return $q->where('status', self::STATUS_PENDING)->whereNotNull('parent_id');
    }

    /* --------------------
     | Helpers
     --------------------*/
    public function markParentApproved()
    {
        $this->status = self::STATUS_PARENT_APPROVED;
        $this->save();
    }

    public function markParentRejected(string $reason = null)
    {
        $this->status = self::STATUS_PARENT_REJECTED;
        if ($reason) {
            $this->notes = trim(($this->notes ?? '') . "\nParent rejection reason: {$reason}");
        }
        $this->retry_count = $this->retry_count + 1;
        $this->save();
    }

    public function incrementRetry()
    {
        $this->increment('retry_count');
    }
}

