namespace App\Models;

use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Factories\HasFactory;

/**
 * Common notification table. Use this to drive Firebase notifications and keep history.
 *
 * Fields:
 *  id, user_id, actor_id (nullable), type, title, body, payload (json), read_at, sent_at, history (json), meta
 *
 * - payload: the platform-specific payload you will send to Firebase
 * - history: array that contains events like ['created_at' => ..., 'attempt' => 1, 'status' => 'sent'|'failed', 'provider_response' => ...]
 */
class Notification extends Model
{
    use HasFactory;

    protected $fillable = [
        'user_id',
        'actor_id',
        'type',
        'title',
        'body',
        'payload',
        'read_at',
        'sent_at',
        'history',
        'meta',
    ];

    protected $casts = [
        'payload' => 'array',
        'history' => 'array',
        'meta' => 'array',
        'sent_at' => 'datetime',
        'read_at' => 'datetime',
    ];

    public function user()
    {
        return $this->belongsTo(User::class, 'user_id');
    }

    public function markSent($providerResponse = null)
    {
        $history = $this->history ?? [];
        $history[] = [
            'at' => now()->toDateTimeString(),
            'status' => 'sent',
            'provider_response' => $providerResponse,
        ];
        $this->history = $history;
        $this->sent_at = now();
        $this->save();
    }

    public function markFailed($providerResponse = null)
    {
        $history = $this->history ?? [];
        $history[] = [
            'at' => now()->toDateTimeString(),
            'status' => 'failed',
            'provider_response' => $providerResponse,
        ];
        $this->history = $history;
        $this->save();
    }

    public function markRead()
    {
        $this->read_at = now();
        $this->save();
    }
}

