        wrap = tk.Frame(self.groups_frame, bg="#1e1f24"); wrap.pack(fill="both", expand=True, padx=8, pady=(0,8))
        self.grp_canvas = tk.Canvas(wrap, bg="#1e1f24", highlightthickness=0)
        vscroll = ttk.Scrollbar(wrap, orient="vertical", command=self.grp_canvas.yview)
