  const PARENS_LETTER_RE = /\(\s*([A-Za-z])\s*\)/g;
  const DATE_TRIPLE_RE = /(\d{4})\s*[.\-:\/]\s*(\d{2})\s*[.\-:\/]\s*(\d{2})/g;
  const YEAR_PAIR_RE = /(\d{4})\s*[\/:\.-]\s*(\d{4})/g;
  const YEAR_PAIR_ABBR_RE = /(\d{4})\s*[\/:\.-]\s*(\d{2})(?!\d)/g;

  function transliteratePreAscii(s){ if(!s) return s; s=s.replace(/ø/g,"o").replace(/Ø/g,"O");
    const map={"ł":"l","Ł":"L","ś":"s","Ś":"S","ć":"c","Ć":"C","ó":"o","Ó":"O","ą":"a","Ą":"A","ę":"e","Ę":"E","ń":"n","Ń":"N","ź":"z","Ź":"Z","ż":"z","Ż":"Z"};
    return s.replace(/[\u0141\u0142\u015A\u015B\u0106\u0107\u00D3\u00F3\u0104\u0105\u0118\u0119\u0143\u0144\u0179\u017A\u017B\u017C]/g, ch=>map[ch]||ch);
  }
  function asciiFold(s){ try{ return s.normalize("NFKD").replace(/[\u0300-\u036f]/g,""); } catch { return s; } }
  function removeStarsBetweenLetters(s){ let prev; do{ prev=s; s=s.replace(/([A-Za-z])\*+([A-Za-z])/g,"$1$2"); } while(s!==prev); return s; }
  function titleToSlug006(title){
    if(!title) return "";
    let s=title.replace(/[⁰¹²³⁴⁵⁶⁷⁸⁹]/g,ch=>SUPERSCRIPTS[ch]||ch);
    s=s.replace(FRACTIONS_RE,"");
    s=transliteratePreAscii(s);
    s=asciiFold(s);
    s=s.replace(/&/g,"");
    s=s.replace(PARENS_LETTER_RE,"$1");
    s=s.replace(DATE_TRIPLE_RE,"$1$2$3");
    s=s.replace(YEAR_PAIR_RE,"$1 __YEAR__ $2").replace(YEAR_PAIR_ABBR_RE,"$1 __YEAR2__ $2");
    s=s.replace(/\//g," __SLASH__ ").replace(/:/g," __COLON__ ");
    s=s.toLowerCase().replace(/['’]/g,"").replace(/\./g,"");
    s=s.replace(/(?<=\d),(?=\d)/g,"");
    s=removeStarsBetweenLetters(s);
    s=s.replace(/(\w)@(?=\w)/g,"$1");
    s=s.replace(/(\w)\$/g,"$1s");
    s=s.replace(/[^a-z0-9_]+/g,"-").replace(/^-+|-+$/g,"");
    s=s.replace(/__year__/g,"¥").replace(/__year2__/g,"¶").replace(/__slash__/g,"§").replace(/__colon__/g,"¤");
    s=s.replace(/(\d)-(?=\d)/g,"$1");
    s=s.replace(/[¥¶§¤]/g,"-").replace(/-+/g,"-");
    return s.replace(/^-+|-+$/g,"");
  }

  function resolveSlugViaBin(id, media, title){
    if(!BIN || !BIN_READY) return { ok:false, reason:"bin not ready" };
    const key = compositeKey(id, media)>>>0;
    const idx = binSearch32(BIN.keys, key);
    if(idx < 0) return { ok:false, reason:"not in bin" };
    const val = BIN.vals[idx]>>>0;
    const type = val & 0x3; // 0=EMPTY,1=YEAR,2=OVERRIDE,3=YEAR_N
    const payload = val >>> 2;
    if(type===2){ return { ok:true, slug: readCString(BIN.blob, payload), type:"OVERRIDE" }; }
    const base = titleToSlug006(title||"");
    if(!base) return { ok:false, reason:"empty base" };
    if(type===0) return { ok:true, slug: ${base}, type:"EMPTY" };
    if(type===1) return { ok:true, slug: ${base}-${payload}, type:"YEAR" };
    if(type===3){ const year = payload>>>7, n = payload & 0x7F; return { ok:true, slug: ${base}-${year}-${n}, type:"YEAR_N" }; }
    return { ok:false, reason:"unknown type" };
  }

  function resolveSlugViaLetterboxd(tmdbId){
    const url = https://letterboxd.com/tmdb/${tmdbId}/;
    return new Promise((resolve)=>{
      GM_xmlhttpRequest({
        method:"HEAD", url, timeout:10000, headers:{Accept:"text/html"},
        onload:(r)=>{
          const f = r.finalUrl || "";
          const m = /^https?:\/\/letterboxd\.com\/film\/([^\/]+)\/?$/i.exec(f);
          resolve(m? m[1] : null);
        },
        onerror:()=>resolve(null),
        ontimeout:()=>resolve(null)
      });
    });
  }

  // Networking (HTML)
  function httpGet(url){
    return new Promise((resolve,reject)=>{
      GM_xmlhttpRequest({
        method:"GET", url, timeout:15000,
        headers:{Accept:"text/html, */*;q=0.8"},
        onload:(res)=>resolve(res.responseText||""), onerror:()=>reject(new Error("network error")), ontimeout:()=>reject(new Error("timeout"))
      });
    });
  }
  function decodeHTML(s){ try{ const d=new DOMParser().parseFromString(s,"text/html"); return d.documentElement.textContent||s; } catch{ return s; } }
  function absUrl(href){ try{ return new URL(href, "https://letterboxd.com").toString(); } catch { return href; } }

  // Keep DOM order & dedupe by ID (Similar)
  function extractSimilar(html){
    const out = [];
    try{
      const doc = new DOMParser().parseFromString(html,"text/html");
      const seen = new Set();
      const nodes = doc.querySelectorAll("[data-film-id]");
      nodes.forEach(el=>{
        const id = el.getAttribute("data-film-id");
        if(!id || seen.has(id)) return;
        seen.add(id);
        let name =
          el.getAttribute("data-item-name") ||
          el.getAttribute("data-film-name") ||
          el.getAttribute("data-item-full-display-name") ||
          el.getAttribute("data-original-title") ||
          el.getAttribute("title") ||
          (el.querySelector("img[alt]")?.getAttribute("alt")) ||
          "";
        name = decodeHTML((name||"").trim()).replace(/\s*\(\d{4}\)\s*$/,"");
        out.push({ id: Number(id), name });
      });
    }catch{}
    return out;
  }

  // Extract Themes/Nanogenres groups (with heading link if present)
  function extractGroups(html){
    const groups = [];
    try{
      const doc = new DOMParser().parseFromString(html,"text/html");
      const sections = doc.querySelectorAll("section.section.genre-group");
      sections.forEach(sec=>{
        const a = sec.querySelector("h2 a[href]");
        const title = (a?.textContent || sec.querySelector("h2 .label")?.textContent || "").trim();
        const hrefRel = a?.getAttribute("href") || null;
        const hrefAbs = hrefRel ? absUrl(hrefRel) : null;

        const seen = new Set();
        const items = [];
        sec.querySelectorAll("[data-film-id]").forEach(el=>{
          const id = el.getAttribute("data-film-id");
          if(!id || seen.has(id)) return;
          seen.add(id);
          let name =
            el.getAttribute("data-item-name") ||
            el.getAttribute("data-film-name") ||
            el.getAttribute("data-item-full-display-name") ||
            el.getAttribute("data-original-title") ||
            el.getAttribute("title") ||
            (el.querySelector("img[alt]")?.getAttribute("alt")) ||
            "";
          name = decodeHTML((name||"").trim()).replace(/\s*\(\d{4}\)\s*$/,"");
          items.push({ id: Number(id), name });
        });
        if(title && items.length) groups.push({ title, href: hrefAbs, items });
      });
    }catch{}
    return groups;
  }

  // AJAX list extractor (tiles + pagination flags)
  function extractAjaxTiles(html){
    const rows = [];
    let hasNext = false, hasPrev = false;
    try{
      const doc = new DOMParser().parseFromString(html,"text/html");
      const seen = new Set();
      const tiles = doc.querySelectorAll('ul.poster-list li [data-film-id]');
      tiles.forEach(el=>{
        const id = el.getAttribute("data-film-id");
        if(!id || seen.has(id)) return;
        seen.add(id);
        let name =
          el.getAttribute("data-item-name") ||
          el.getAttribute("data-film-name") ||
          el.getAttribute("data-item-full-display-name") ||
          el.getAttribute("data-original-title") ||
          el.getAttribute("title") ||
          (el.querySelector("img[alt]")?.getAttribute("alt")) ||
          "";
        name = decodeHTML((name||"").trim()).replace(/\s*\(\d{4}\)\s*$/,"");
        rows.push({ id:Number(id), name });
      });
      const pag = doc.querySelector(".pagination");
      if (pag){
        hasNext = !!pag.querySelector("a.next");
        hasPrev = !!pag.querySelector("a.previous, a.prev");
      }
    }catch{}
    return { rows, hasNext, hasPrev };
  }

  // Convert a listing URL → its AJAX URL for page N
  function toAjaxUrl(listingUrl, page){
    try{
      const u = new URL(listingUrl, "https://letterboxd.com");
      const parts = u.pathname.split("/").filter(Boolean); // ["films","theme",...]
      const idxFilms = parts.indexOf("films");
      if (idxFilms === -1) return listingUrl;
      if (parts[idxFilms+1] !== "ajax") parts.splice(idxFilms+1, 0, "ajax");
      const basePath = "/" + parts.join("/") + /page/${page}/;
      const out = ${u.origin}${basePath}?esiAllowFilters=true;
      return out;
    }catch{
      return listingUrl;
    }
  }

