    // Map<number, { mapped:Array, hasNext:boolean, hasPrev:boolean, csv:string, mapMs:number }>
    const pageCache = new Map();

    async function fetchAndMap(page){
      const urlAjax = toAjaxUrl(ctx.href, page);
      let html = "";
      try { html = await httpGet(urlAjax); }
      catch { throw new Error("network"); }
      const { rows, hasNext, hasPrev } = extractAjaxTiles(html);

      const t0 = performance.now();
      const pairs = LBD?.pairs;
      let matched = 0;
      const mapped = rows.map(r=>{
        if (pairs){
          const packed = lbdPackedLookup(pairs, r.id>>>0);
          if (packed !== undefined){ const {tmdbId,isTv} = unpackPacked(packed); matched++; return {...r, tmdbId, isTv}; }
        }
        return {...r, tmdbId:null, isTv:false};
      });
      const mapMs = Math.max(0, Math.round(performance.now()-t0));

      const csv = "lbx_id,name,tmdb_id,is_tv\n" + mapped.map(r=>{
        const name = (r.name||"").replace(/"/g,'""');
        const tmdb = (r.tmdbId ?? "");
        const isTv = r.isTv ? 1 : 0;
        return ${r.id},"${name}",${tmdb},${isTv};
      }).join("\n");

      return { mapped, hasNext, hasPrev, csv, mapMs, matched };
    }

    function paint(page, data){
      const { mapped, hasNext, hasPrev, csv, mapMs, matched } = data;
      box.innerHTML =
        <h3>${escapeHtml(kind)} — ${escapeHtml(ctx.title)}</h3>
