          <div>Page:</div><div>${page}</div>
          <div>Items:</div><div><b>${mapped.length}</b> <span class="muted">(matched ${matched})</span></div>
          <div>Map time:</div><div>${mapMs} ms</div>
        </div>
        <div class="t2sl-list">
          <table>
            <thead>
              <tr>
                <th style="width:130px;">Letterboxd ID</th>
                <th>Title</th>
                <th style="width:130px;">TMDb ID</th>
