              ${mapped.map(r=><tr>
                <td><code>${r.id}</code></td>
                <td>${escapeHtml(r.name||"")}</td>
                <td>${r.tmdbId != null ? <code>${r.tmdbId}</code> : <span class="muted">—</span>}</td>
                <td>${r.isTv ? 1 : 0}</td>
              </tr>).join("")}
            </tbody>
          </table>
        </div>
        <div class="t2sl-actions">
          <button class="btn copy" id="t2sl-copy">Copy CSV</button>
          <div style="flex:1"></div>
          <div class="t2sl-nav">
            <button class="btn" id="t2sl-prev" ${(hasPrev || page>1) ? "" : "disabled"}>◀ Prev</button>
