function create(tag, onConnect) {
  const el = document.createElement(tag);
  if (onConnect) {
    let observer;
    const check = () => {
      if (el.isConnected) {
        observer.disconnect();
        onConnect(el);
      }
    };
    observer = new MutationObserver(check);

    // Observe the document to catch ancestor removals too
    observer.observe(document, { childList: true, subtree: true });

    // Optional: quick check in case already connected
    check();
  }
  return el;
}

