// --- Fake API endpoints ---
const API_URL = 'https://example.com/api/names' // replace with your backend

const fetchNames = async () => {
  const res = await axios.get(API_URL)
  return res.data
}

const addName = async (newName: string) => {
  const res = await axios.post(API_URL, { name: newName })
  return res.data
}

// --- Component ---
export default function NamesPage() {
  const queryClient = useQueryClient()
  const [newName, setNewName] = useState('')

  // Fetch names
  const { data: names, isLoading, isError } = useQuery({
    queryKey: ['names'],
    queryFn: fetchNames,
  })

  // Mutation to add a new name
  const mutation = useMutation({
    mutationFn: addName,
    onSuccess: () => {
      // invalidate to refetch updated list
      queryClient.invalidateQueries({ queryKey: ['names'] })
      setNewName('')
    },
  })

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault()
    if (!newName.trim()) return
    mutation.mutate(newName)
  }

  if (isLoading) return <p>Loading...</p>
  if (isError) return <p>Error loading names.</p>

  return (
    <div style={{ padding: '2rem' }}>
      <h1>Names</h1>

      <ul>
        {names?.map((n: any) => (
          <li key={n.id}>{n.name}</li>
        ))}
      </ul>

      <form onSubmit={handleSubmit} style={{ marginTop: '1rem' }}>
        <input
          type="text"
          value={newName}
          onChange={(e) => setNewName(e.target.value)}
          placeholder="Enter a name"
        />
        <button type="submit" disabled={mutation.isPending}>
          {mutation.isPending ? 'Adding...' : 'Add'}
        </button>
      </form>
    </div>
  )
}

