const mutation = useMutation({
  mutationFn: addName,
  onMutate: async (newName) => {
    // Cancel any outgoing refetches
    await queryClient.cancelQueries({ queryKey: ['names'] })

    // Snapshot previous value
    const previousNames = queryClient.getQueryData(['names'])

    // Optimistically update cache
    queryClient.setQueryData(['names'], (old) => [...(old ?? []), { id: Date.now(), name: newName }])

    return { previousNames }
  },
  onError: (err, newName, context) => {
    // Rollback on error
    queryClient.setQueryData(['names'], context?.previousNames)
  },
  onSettled: () => {
    // Revalidate to ensure server is source of truth
    queryClient.invalidateQueries({ queryKey: ['names'] })
  },
})

