    const reachedMaxDetail =
      targetZ >= maxZ || this.children.length === 0 || this.z === maxZ;
    if (reachedMaxDetail) {
      this.selected = true;
      return true;
    }

    let hasVisibleChild = false;
    for (const child of this.children) {
      hasVisibleChild = child.update(params) || hasVisibleChild;
    }
    if (!hasVisibleChild) {
      this.selected = true;
      return true;
