function rescaleEPSG3857ToCommonSpace([x, y]: [number, number]): [
  number,
  number,
] {
  return [
    (x / EPSG_3857_CIRCUMFERENCE + 0.5) * TILE_SIZE,
    (0.5 - y / EPSG_3857_CIRCUMFERENCE) * TILE_SIZE,
  ];
