function rescaleEPSG3857ToCommonSpace([x, y]: [number, number]): [number, number] {
  const HALF = EPSG_3857_CIRCUMFERENCE / 2;

  const clampedY = Math.max(-HALF, Math.min(HALF, y));

  return [
    (x / EPSG_3857_CIRCUMFERENCE + 0.5) * TILE_SIZE,
    (0.5 - clampedY / EPSG_3857_CIRCUMFERENCE) * TILE_SIZE,
  ];
}

