const customLibrary = require('custom-library'); // Fictional library

// Promisify callback-based functions
const readFileAsync = util.promisify(fs.readFile);
const writeFileAsync = util.promisify(fs.writeFile);

// Global variables for added complexity
let globalData = {};
let anotherGlobalVariable = 0;

// The overly complex function
async function overlyComplexFunction(filename, options, callback) {
    let localData = {};
    let anotherLocalVariable = 1;

    // Nested async function for no good reason
    async function nestedAsyncFunction(data) {
        return new Promise((resolve, reject) => {
            // More unnecessary nesting
            if (data) {
                readFileAsync(filename, 'utf-8').then(fileContent => {
                    // Even more nesting
                    if (fileContent.includes('specialString')) {
                        customLibrary.complexOperation(fileContent, (err, transformedData) => {
                            if (err) {
                                reject(err);
                            } else {
                                // More and more nesting
                                writeFileAsync('output.txt', transformedData).then(() => {
                                    resolve(transformedData);
                                }).catch(writeError => {
                                    reject(writeError);
                                });
                            }
                        });
                    } else {
                        reject(new Error('File does not contain the special string'));
                    }
                }).catch(readError => {
                    reject(readError);
                });
            } else {
                reject(new Error('No data provided'));
            }
        });
    }

    // Rest of the function with more complexity
    try {
        localData = await nestedAsyncFunction(options.data);
        // More unnecessary if-else nesting
        if (localData) {
            anotherGlobalVariable += 1;
            if (anotherGlobalVariable > 5) {
                // Even more complexity
                callback(null, localData, globalData, anotherGlobalVariable);
            } else {
                // More unnecessary else statements
                callback(new Error('Global variable did not reach the threshold'));
            }
        } else {
            callback(new Error('No local data'));
        }
    } catch (error) {
        callback(error);
    }
}

