# Replace with your own YouTube Data API key
API_KEY = "YOUR_API_KEY"

# Replace with your OAuth 2.0 Client ID and Secret
CLIENT_SECRETS_FILE = "YOUR_CLIENT_SECRET_FILE.json"

# This is the list of songs we want to add to the playlist
songs = [
    "Billy Idol - Rebel Yell", "Billy Idol - White Wedding", "Billy Idol - Dancing With Myself",
    "Billy Idol - Eyes Without a Face", "Billy Idol - Mony Mony",
    "David Bowie - Heroes", "David Bowie - Space Oddity", "David Bowie - Let's Dance",
    "David Bowie - Life on Mars?", "David Bowie - Ziggy Stardust",
    # Add more songs here...
]

# Create a YouTube API client
scopes = ["https://www.googleapis.com/auth/youtube.force-ssl"]

def get_authenticated_service():
    flow = google_auth_oauthlib.flow.InstalledAppFlow.from_client_secrets_file(
        CLIENT_SECRETS_FILE, scopes)
    credentials = flow.run_console()
    return googleapiclient.discovery.build("youtube", "v3", credentials=credentials)

def create_playlist(youtube, title, description):
    request = youtube.playlists().insert(
        part="snippet,status",
        body={
            "snippet": {
                "title": title,
                "description": description
            },
            "status": {
                "privacyStatus": "public"
            }
        }
    )
    response = request.execute()
    return response["id"]

def search_song(youtube, query):
    request = youtube.search().list(
        part="snippet",
        maxResults=1,
        q=query,
        type="video"
    )
    response = request.execute()
    return response["items"][0]["id"]["videoId"]

def add_song_to_playlist(youtube, playlist_id, video_id):
    request = youtube.playlistItems().insert(
        part="snippet",
        body={
            "snippet": {
                "playlistId": playlist_id,
                "resourceId": {
                    "kind": "youtube#video",
                    "videoId": video_id
                }
            }
        }
    )
    request.execute()

def main():
    youtube = get_authenticated_service()

    playlist_id = create_playlist(youtube, "Classic and Alternative Rock Essentials", "A playlist of classic and alternative rock songs.")

    for song in songs:
        try:
            video_id = search_song(youtube, song)
            add_song_to_playlist(youtube, playlist_id, video_id)
            print(f"Added {song} to playlist.")
        except Exception as e:
            print(f"Could not add {song}: {e}")

if __name__ == "__main__":
    main()

