using System;
using System.Collections.Generic;
using System.Linq;
using System.Text.RegularExpressions;

namespace GenShaderBinding.SourceGeneration
{
    /// <summary>
    /// Responsible for matching input variables in the shader source code with the
    /// corresponding members of vertex structures in C#.
    /// e.g. matching the 'a_Position' attribute in the shader with the 'Vertex.Position' member
    /// </summary>
    internal class ShaderInputMatching
    {
        public static string GetInputVariableName(
            VariableDeclaration vertexField,
            IEnumerable<VariableDeclaration> glslAttributes)
        {
            var csharpWords = NormalizeCSharpName(vertexField.Name).ToList();

            string bestMatch = null;
            int bestScore = -1;

            foreach (var glslAttribute in glslAttributes)
            {
                var glslWords = NormalizeGlslName(glslAttribute.Name).ToList();

                // Compute the number of matching words
                int score = csharpWords.Intersect(glslWords).Count();

                if (score > bestScore)
                {
                    bestScore = score;
                    bestMatch = glslAttribute.Name;
                }
            }

            if (bestMatch != null && bestScore > 0)
            {
                return bestMatch;
            }

            throw new Exception($"No matching attribute found for vertex field '{vertexField.Name}'");
        }

        private static IEnumerable<string> NormalizeCSharpName(string csharpName)
        {
            // Split PascalCase
            var words = Regex.Matches(csharpName, @"([A-Z][a-z0-9]*)")
                .Cast<Match>()
                .Select(m => NormalizeWord(m.Value));
            return words;
        }

        private static IEnumerable<string> NormalizeGlslName(string glslName)
        {
            // Remove prefixes
            var name = glslName;
            if (name.StartsWith("a_") || name.StartsWith("v_") || name.StartsWith("u_"))
            {
                name = name.Substring(2);
            }
            // Split on underscores
            var words = name.Split('_').Select(w => NormalizeWord(w));
            return words;
        }

        private static string NormalizeWord(string word)
        {
            switch (word.ToLowerInvariant())
            {
                case "pos":
                case "position":
                    return "position";
                case "nrm":
                case "normal":
                    return "normal";
                case "uv":
                case "texcoord":
                    return "texcoord";
                case "col":
                case "colour":
                case "color":
                    return "color";
                case "vert":
                case "vertex":
                    return "vertex";
                case "tangent":
                    return "tangent";
                case "binormal":
                case "bi_normal":
                    return "binormal";
                case "boneweights":
                case "bone_weights":
                    return "boneweights";
                case "boneindices":
                case "bone_indices":
                    return "boneindices";
                default:
                    return word.ToLowerInvariant();
            }
        }
    }
}

