    <label for="accountNo">Bank Account Number:</label>
    <input type="text" id="accountNo" name="accountNo" placeholder="Enter your bank account number" required>
    <div id="accountNoError" class="error"></div>

    <label for="ifscCode">IFSC Code:</label>
    <input type="text" id="ifscCode" name="ifscCode" placeholder="Enter your IFSC code" required>
    <div id="ifscCodeError" class="error"></div>

    <label for="accountHolderName">Account Holder Name:</label>
    <input type="text" id="accountHolderName" name="accountHolderName" placeholder="Enter account holder's name" required>
    <div id="accountHolderNameError" class="error"></div>

    <label for="charges">Transaction Charges (in %):</label>
    <select id="charges" name="charges" required>
      <option value="">Select Transaction Charges</option>
      <option value="1">1%</option>
      <option value="1.5">1.5%</option>
      <option value="2">2%</option>
    </select>

    <button type="button" class="btn" onclick="proceedToPayment()">Proceed to Payment</button>
  </form>

  <script>
    // Prefill amount from main code
    function setAmount(amount) {
      document.getElementById("amount").value = amount;
    }

    function validateForm() {
      let isValid = true;

      // Clear previous error messages
      document.getElementById("accountNoError").innerText = '';
      document.getElementById("ifscCodeError").innerText = '';
      document.getElementById("accountHolderNameError").innerText = '';

      // Validate Bank Account Number
      const accountNo = document.getElementById("accountNo").value;
      if (!/^\d{1,17}$/.test(accountNo)) {
        document.getElementById("accountNoError").innerText = 'Bank Account Number must be 1-17 digits.';
        isValid = false;
      }

      // Validate IFSC Code
      const ifscCode = document.getElementById("ifscCode").value;
      if (!/^[A-Z]{4}0[A-Z0-9]{6}$/.test(ifscCode)) {
        document.getElementById("ifscCodeError").innerText = 'IFSC Code must be exactly 11 characters (Format: ABCD0123456).';
        isValid = false;
      }

      // Validate Account Holder Name
      const accountHolderName = document.getElementById("accountHolderName").value;
      if (!/^[A-Za-z\s]+$/.test(accountHolderName)) {
        document.getElementById("accountHolderNameError").innerText = 'Account Holder Name must contain only alphabetic characters.';
        isValid = false;
      }

      return isValid;
    }

    function proceedToPayment() {
      if (validateForm()) {
        const amount = document.getElementById("amount").value;
        const accountNo = document.getElementById("accountNo").value;
        const ifscCode = document.getElementById("ifscCode").value;
        const accountHolderName = document.getElementById("accountHolderName").value;
        const charges = document.getElementById("charges").value;

        // In a real implementation, pass these values to your server, then call a payment API
        alert(`Amount: ${amount}\nAccount No: ${accountNo}\nIFSC Code: ${ifscCode}\nAccount Holder Name: ${accountHolderName}\nTransaction Charges: ${charges}%\nProceeding with Payment...`);

        // Redirect or integrate with a payment processor API
        // window.location.href = "https://yourpaymentgateway.com/checkout";
      }
    }

