<body class="bg-gray-100 p-8">
    <div class="max-w-2xl mx-auto bg-white p-6 rounded-lg shadow-md">
        <h1 class="text-2xl font-bold mb-4">PDF Comparison Tool</h1>
        <form id="folderForm" class="space-y-4">
            <div>
                <label for="sourceFolder" class="block text-sm font-medium text-gray-700">Source Folder:</label>
                <button id="sourceFolder" class="mt-1 block w-full py-2 px-3 border border-gray-300 bg-white rounded-md shadow-sm focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm">
                    Select Source Folder
                </button>
            </div>
            <div>
                <label for="compareFolder" class="block text-sm font-medium text-gray-700">Compare Folder:</label>
                <button id="compareFolder" class="mt-1 block w-full py-2 px-3 border border-gray-300 bg-white rounded-md shadow-sm focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm">
                    Select Compare Folder
                </button>
            </div>
            <div>
                <label for="destFolder" class="block text-sm font-medium text-gray-700">Destination Folder:</label>
                <button id="destFolder" class="mt-1 block w-full py-2 px-3 border border-gray-300 bg-white rounded-md shadow-sm focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm">
                    Select Destination Folder
                </button>
            </div>
