                Run Comparison
            </button>
        </form>
        <div id="output" class="mt-8">
            <h2 class="text-xl font-semibold mb-2">Output:</h2>
            <pre id="outputContent" class="bg-gray-100 p-4 rounded-md whitespace-pre-wrap"></pre>
        </div>
    </div>

    <script>
        let sourceFolderHandle, compareFolderHandle, destFolderHandle;

        async function getDirectoryHandle(buttonId) {
            try {
                const handle = await window.showDirectoryPicker();
                document.getElementById(buttonId).textContent = handle.name;
                return handle;
            } catch (err) {
                console.error(err);
                return null;
            }
        }

        document.getElementById('sourceFolder').addEventListener('click', async (e) => {
            e.preventDefault();
            sourceFolderHandle = await getDirectoryHandle('sourceFolder');
        });

        document.getElementById('compareFolder').addEventListener('click', async (e) => {
            e.preventDefault();
            compareFolderHandle = await getDirectoryHandle('compareFolder');
        });

        document.getElementById('destFolder').addEventListener('click', async (e) => {
            e.preventDefault();
            destFolderHandle = await getDirectoryHandle('destFolder');
        });

        async function getPdfFiles(folderHandle, firstLayerOnly = false) {
            const pdfFiles = [];

            async function collectFiles(handle, depth = 0) {
                for await (const entry of handle.values()) {
                    if (entry.kind === 'file' && entry.name.toLowerCase().endsWith('.pdf')) {
                        pdfFiles.push(entry);
                    } else if (entry.kind === 'directory' && depth === 0) {
                        await collectFiles(entry, depth + 1);
                    }
                }
            }

            await collectFiles(folderHandle, firstLayerOnly ? 1 : 0);
            return pdfFiles;
        }

        async function moveFile(sourceFile, destFolderHandle) {
            const source = await sourceFile.getFile();
            const destFileHandle = await destFolderHandle.getFileHandle(sourceFile.name, { create: true });
            const writable = await destFileHandle.createWritable();
            await writable.write(source);
            await writable.close();
            await sourceFile.remove();  // Move by deleting from source after copying
        }

        async function compareAndMovePdfs(sourcePdfs, comparePdfs, destFolderHandle) {
            const matches = [];
            const comparePdfNames = comparePdfs.map(pdf => pdf.name.split('.')[0]);

            for (const sourcePdf of sourcePdfs) {
                const sourceName = sourcePdf.name.split('.')[0];
                let bestMatch = null;
                let highestRatio = 0;

                for (let i = 0; i < comparePdfNames.length; i++) {
                    const compareName = comparePdfNames[i];
                    const ratio = getSequenceMatchRatio(sourceName, compareName);
                    if (ratio > 0.9 && ratio > highestRatio) {
                        highestRatio = ratio;
                        bestMatch = comparePdfs[i];
                    }
                }

                if (bestMatch) {
                    const sourcePages = await getPdfPageCount(sourcePdf);
                    const comparePages = await getPdfPageCount(bestMatch);

                    if (sourcePages === comparePages) {
                        await moveFile(sourcePdf, destFolderHandle);

                        matches.push({
                            source: sourcePdf.name,
                            compare: bestMatch.name,
                            destination: sourcePdf.name
                        });
                    }
                }
            }

            return matches;
        }

        document.getElementById('folderForm').addEventListener('submit', async function(e) {
            e.preventDefault();

            if (!sourceFolderHandle || !compareFolderHandle || !destFolderHandle) {
                alert('Please select all folders before running the comparison.');
                return;
            }

            const outputContent = document.getElementById('outputContent');
            outputContent.textContent = 'Processing...';

            try {
                const sourcePdfs = await getPdfFiles(sourceFolderHandle);
                const comparePdfs = await getPdfFiles(compareFolderHandle, true);

                const matches = await compareAndMovePdfs(sourcePdfs, comparePdfs, destFolderHandle);

                let output = '';
                for (const match of matches) {
                    output += `Source: ${match.source}\n`;
                    output += `Compare: ${match.compare}\n`;
                    output += `Destination: ${match.destination}\n\n`;
                }

                outputContent.textContent = output || 'No matches found.';

                const outputFileHandle = await destFolderHandle.getFileHandle('output.txt', { create: true });
                const writable = await outputFileHandle.createWritable();
                await writable.write(output);
                await writable.close();

            } catch (error) {
                console.error(error);
                outputContent.textContent = `An error occurred: ${error.message}`;
            }
        });

        pdfjsLib.GlobalWorkerOptions.workerSrc = 'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/2.9.359/pdf.worker.min.js';
    </script>
</body>
