            Console.WriteLine("Press 'Esc' to exit.");

            while (true)
            {
                if (ReadConsoleInput(inputHandle, records, 1, out eventsRead))
                {
                    foreach (var record in records)
                    {
                        if (record.EventType == MOUSE_EVENT)
                        {
                            COORD position = record.MouseEvent.dwMousePosition;
                            bool leftButtonDown = (record.MouseEvent.dwButtonState & FROM_LEFT_1ST_BUTTON_PRESSED) != 0;
                            bool leftButtonReleased = (record.MouseEvent.dwButtonState == 0); // No button pressed

                            // Check for left button press inside the rectangle
                            if (leftButtonDown && pressPosition == null)
                            {
                                if (IsInsideRectangle(position, rectTopLeftX, rectTopLeftY, rectBottomRightX, rectBottomRightY))
                                {
                                    pressPosition = position;
                                    Console.SetCursorPosition(0, 25);
                                    Console.WriteLine(string.Format("Left button pressed at ({0}, {1}).            ", position.X, position.Y));
                                }
                            }

                            // Check for left button release
                            if (leftButtonReleased && pressPosition != null)
                            {
                                if (IsInsideRectangle(position, rectTopLeftX, rectTopLeftY, rectBottomRightX, rectBottomRightY))
                                {
                                    Console.SetCursorPosition(0, 26);
                                    Console.WriteLine(string.Format("Left button released at ({0}, {1}). Click completed inside rectangle.            ", position.X, position.Y));
                                }
                                else
                                {
                                    Console.SetCursorPosition(0, 26);
                                    Console.WriteLine("Release occurred outside rectangle.            ");
                                }

                                // Reset press state
                                pressPosition = null;
                            }
                        }

                        // Exit on ESC key press
                        if (Console.KeyAvailable && Console.ReadKey(true).Key == ConsoleKey.Escape)
                        {
                            return;
                        }
                    }
                }
            }
        }

        static bool IsInsideRectangle(COORD position, int rectTopLeftX, int rectTopLeftY, int rectBottomRightX, int rectBottomRightY)
        {
            return position.X >= rectTopLeftX && position.X <= rectBottomRightX &&
                   position.Y >= rectTopLeftY && position.Y <= rectBottomRightY;
        }
    }
