package main

import (
	"encoding/json"
	"fmt"
	"os"
	"os/signal"
	"path/filepath"
	"sync"
	"syscall"

	"github.com/micmonay/keyboard"
)

const dataFile = "key_counts.json"

var (
	keyCounts map[string]int
	mu        sync.Mutex
)

func loadCounts() {
	keyCounts = make(map[string]int)
	file, err := os.Open(dataFile)
	if err != nil {
		return
	}
	defer file.Close()
	json.NewDecoder(file).Decode(&keyCounts)
}

func saveCounts() {
	mu.Lock()
	defer mu.Unlock()
	file, err := os.Create(dataFile)
	if err != nil {
		fmt.Println("Error saving:", err)
		return
	}
	defer file.Close()
	enc := json.NewEncoder(file)
	enc.SetIndent("", "  ")
	enc.Encode(keyCounts)
}

func main() {
	loadCounts()
	defer saveCounts()

	if err := keyboard.Open(); err != nil {
		panic(err)
	}
	defer keyboard.Close()

	fmt.Println("Tracking key presses. Press ESC to quit.")

	// Handle CTRL+C / SIGINT for safe shutdown
	go func() {
		c := make(chan os.Signal, 1)
		signal.Notify(c, os.Interrupt, syscall.SIGTERM)
		<-c
		saveCounts()
		fmt.Println("\nExiting. Saved key counts.")
		os.Exit(0)
	}()

	for {
		char, key, err := keyboard.GetKey()
		if err != nil {
			panic(err)
		}
		keyStr := ""
		if key != 0 {
			keyStr = key.String()
		} else {
			keyStr = string(char)
		}
		mu.Lock()
		keyCounts[keyStr]++
		mu.Unlock()
		saveCounts()

		if key == keyboard.KeyEsc {
			break
		}
	}
}

