struct StepResult { bool accepted; double h_new; double err; };

StepResult rk45_step_and_update(double t, double h,
                                const Vector& y,
                                Vector& y5_out, // order-5 accepted candidate
                                Func f,
                                const Vector& atol, const Vector& rtol,
                                double safety=0.9, double minfac=0.2, double maxfac=5.0)
{
    // 1) Do RK stages -> y5 (order-5) and y4 (embedded order-4)
    Vector y5, y4;
    rk45_compute_embedded(t, h, y, f, y5, y4);

    // 2) Scaled error (RMS)
    Vector sc = atol + rtol.cwiseProduct( y.cwiseAbs().cwiseMax(y5.cwiseAbs()) );
    Vector z  = (y5 - y4).cwiseQuotient(sc);
    double err = std::sqrt(z.squaredNorm() / z.size()); // RMS

    // 3) Controller exponent for RK45: 1/(p+1) with p=4 -> 0.2
    constexpr double expo = 1.0 / 5.0;

    // Protect against err==0
    double fac = (err > 0.0) ? std::pow(err, -expo) : maxfac;
    double growth = safety * fac;
    growth = std::min(maxfac, std::max(minfac, growth));
    double h_new = h * growth;

    if (err <= 1.0) {
        y5_out = std::move(y5);
        return {true, h_new, err};
    } else {
        return {false, h_new, err}; // caller retries with h_new
    }
}

