// Clean Fehlberg step: builds k1..k6, returns y5 and e = y5 - y4
inline void fehlberg54_step(
    auto&& f, double t, double h, 
    span<const double> y,
    span<const double> k1, span<const double> k2, span<const double> k3,
    span<const double> k4, span<const double> k5, span<const double> k6,
    span<double> y5, span<double> err)
{
    // k1 = f(t, y) is assumed supplied (reuse from previous step if you like)
    // k2
    f(t + h/4.0,    y + (h/4.0)*k1, k2);
    // k3
    f(t + 3*h/8.0,  y + h*(3.0/32.0*k1 + 9.0/32.0*k2), k3);
    // k4
    f(t + 12*h/13., y + h*(1932./2197.*k1 - 7200./2197.*k2 + 7296./2197.*k3), k4);
    // k5
    f(t + h,        y + h*(8341./4104.*k1 - 32832./4104.*k2 + 29440./4104.*k3 - 845./4104.*k4), k5);
    // k6
    f(t + h/2.0,    y + h*(-6080./20520.*k1 + 41040./20520.*k2 - 28352./20520.*k3
                           + 9295./20520.*k4 - 5643./20520.*k5), k6);

    // y5 (order-5)
    y5 = y + h*( 16./135.*k1 + 6656./12825.*k3 + 28561./56430.*k4 - 9./50.*k5 + 2./55.*k6 );
    // y4 (order-4) → form error directly
    auto y4 = y + h*( 25./216.*k1 + 1408./2565.*k3 + 2197./4104.*k4 - 1./5.*k5 );
    err = y5 - y4;
}

