/// <summary>
/// Defines the workspace memory needed for the RK45 method in the GPU.
/// </summary>
/// <typeparam name="T"></typeparam>
/// <typeparam name="N"></typeparam>
template <typename T, size_t N>
struct RK45WorskspaceGpu
{
	T* k1;
	T* k2;
	T* k3;
	T* k4;
	T* k5;
	T* k6;
	T* yTemp; // Temporary storage for intermediate y values
	T* timestep;

	T* rawMemory;

	__host__ __device__ RK45WorskspaceGpu()
	{
		cudaMalloc((void**)&rawMemory, sizeof(T) * (7 * N + 1));
		k1 = rawMemory;
		k2 = k1 + N;
		k3 = k2 + N;
		k4 = k3 + N;
		k5 = k4 + N;
		k6 = k5 + N;
		yTemp = k6 + N;
		timestep = yTemp + N;
		cudaMemset(timestep, 0, sizeof(T));
	}
	__host__ __device__ ~RK45WorskspaceGpu()
	{
		cudaFree(rawMemory);
	}
};

template <typename T, size_t N>
class RK45
{
public:
	RK45(AutonomousProblem<T, N>& autonomousProblem, DataLogger<T, N>& logger, double tstep = 1e-2);
	~RK45();

