template <typename T, size_t N, class Pair>  // Pair = DP54 or RKF45
class RK45 {
public:
  RK45(AutonomousProblem<T,N>& P, DataLogger<T,N>& L, double h0=1e-3,
       double rtol=1e-6, double atol=1e-12)
  : problem(P), logger(L), h(h0), rtol(rtol), atol(atol), ws(N) {}

  struct Result { bool accepted; double err; double h_suggested; };

  void initialize(const T* y0_host, bool onDevice=false) {
    if (onDevice) CUDA_CHECK(cudaMemcpy(ws.ytmp, y0_host, N*sizeof(T), cudaMemcpyDeviceToDevice));
    else          CUDA_CHECK(cudaMemcpy(ws.ytmp, y0_host, N*sizeof(T), cudaMemcpyHostToDevice));
    CUDA_CHECK(cudaMemcpy(ws.h_dev, &h, sizeof(double), cudaMemcpyHostToDevice));
  }

  Result runStep(int step_idx){
    // k1 = f(y)
    problem.run(ws.ytmp, ws.k1);

    // stages k2..k6
    for (int s=1; s<Pair::S; ++s){
      build_stage_ytmp(s);             // ytmp = y + h * Σ a[s][j]*k[j]
      problem.run(ws.ytmp, stage_ptr(s));
    }

    // y5 and error vector
    combine_b(ws.ytmp, ws.k1, ws.k2, ws.k3, ws.k4, ws.k5, ws.k6, h, Pair::b5, y5_dev);
    error_vec(ws.k1, ws.k2, ws.k3, ws.k4, ws.k5, ws.k6, h, Pair::b5, Pair::b4, err_dev);

    double err = scaled_norm(err_dev, ws.ytmp, y5_dev, rtol, atol, N); // device reduction -> host scalar

    double h_new = controller(h, err);

    if (err <= 1.0){
      // accept: y = y5
      CUDA_CHECK(cudaMemcpy(ws.ytmp, y5_dev, N*sizeof(T), cudaMemcpyDeviceToDevice));
      h = h_new;
      CUDA_CHECK(cudaMemcpy(ws.h_dev, &h, sizeof(double), cudaMemcpyHostToDevice));
      if (logger.shouldCopy(step_idx)) logger.setReadyToCopy(ws.ytmp);
      return {true, err, h};
