StepResult do_one_rk45_step(double& h) {
    for (;;) {  // retry loop
        // 1) Stages k1..k6 (autonomous: k1 can be reused on rejection)
        problem.run(ws.ytmp, ws.k1);
        build_stage_ytmp(2); problem.run(ws.ytmp, ws.k2);
        build_stage_ytmp(3); problem.run(ws.ytmp, ws.k3);
        build_stage_ytmp(4); problem.run(ws.ytmp, ws.k4);
        build_stage_ytmp(5); problem.run(ws.ytmp, ws.k5);
        build_stage_ytmp(6); problem.run(ws.ytmp, ws.k6);

        // 2) Form y5 (order-5) and err vector e = y5 - y4
        combine_b5(/*k's*/, h, y5_dev);
        diff_b5_b4(/*k's*/, h, e_dev);

        // 3) Compute mixed abs/rel norm (RMS or max) on device → host scalar
        double err = scaled_error_norm(e_dev, ws.ytmp, y5_dev, rtol, atol);

        // 4) Controller (RK45 => exponent = 1/5)
        double h_new;
        if (err == 0.0) {
            h_new = std::min(5.0, 5.0) * h; // max growth
        } else {
            double fac = 0.9 * std::pow(err, -1.0/5.0);
            fac = std::clamp(fac, 0.2, 5.0);
            h_new = h * fac;
        }

        if (err <= 1.0) {
            // accept: y = y5, advance h
            CUDA_CHECK(cudaMemcpy(ws.ytmp, y5_dev, N*sizeof(T), cudaMemcpyDeviceToDevice));
            h = h_new;
            return {true, h, err};
        } else {
            // reject: shrink and retry; forbid growth on this retry
            double fac = 0.9 * std::pow(err, -1.0/5.0);
            h = h * std::max(0.2, std::min(1.0, fac));  // clamp and no growth
            // loop repeats with smaller h
        }
    }
}

