          const auto solar_1_state = id(solar_1_DEVICE_STATE).state;
          // if (solar20_state == solar_1_state) {
          //   it.printf(x1i + icon_pad, y, id(font_value), TextAlign::BASELINE_LEFT, solar20_state.c_str());
          // } else {
          //   if(solar20_state == "" || solar20_state == "Off") {
          //     it.printf(x1i + icon_pad, y, id(font_value), TextAlign::BASELINE_LEFT, solar_1_state.c_str());
          //   } else if(solar_1_state == "" || solar_1_state == "Off") {
          //     it.printf(x1i + icon_pad, y, id(font_value), TextAlign::BASELINE_LEFT, solar20_state.c_str());
          //   } else {
          //     it.printf(x1i + icon_pad, y, id(font_value), TextAlign::BASELINE_LEFT, "%s %s", solar20_state.c_str(),
          //     solar_1_state.c_str());
          //   }
          // }
          it.printf(x1i + icon_pad, y, id(font_value), TextAlign::BASELINE_LEFT, solar_1_state.c_str());
        }

      } else {
        // Page 2 (using second Smart shunt and Smart Solar)
        // Display data from second Smart Shunt
        // shunt_2_BATTERY_VOLTAGE
        y += cat_pad;
        it.printf(x1i, y, id(font_icons_small), TextAlign::BASELINE_CENTER, id(shunt_2_STATE_OF_CHARGE_symbol).state.c_str());
        if (!std::isnan(id(shunt_2_BATTERY_VOLTAGE).state) && id(victron_present)) {
          it.printf(x1i + icon_pad, y, id(font_value), TextAlign::BASELINE_LEFT, "%.2f V", id(shunt_2_BATTERY_VOLTAGE).state);
        }

        // shunt_2_STATE_OF_CHARGE
        y += cat_pad;
        it.printf(x1i, y, id(font_icons_small), TextAlign::BASELINE_CENTER, id(shunt_2_STATE_OF_CHARGE_symbol).state.c_str());
        if (!std::isnan(id(shunt_2_STATE_OF_CHARGE).state) && id(victron_present)) {
