          } else {
            it.printf(x1i + icon_pad, y, id(font_value), TextAlign::BASELINE_LEFT, "%.1f %%", id(shunt_2_STATE_OF_CHARGE).state);
          }
        }

        // Battery time remaining
        y += cat_pad;
        it.printf(x1i, y, id(font_icons_small), TextAlign::BASELINE_CENTER, "\U000F051F");  // mdi-timer-sand
        if (!std::isnan(id(shunt_2_TIME_TO_GO).state) && id(victron_present)) {
