<script type="module">
  // Use the official browser ESM build (ships with .mjs + .wasm)
  // API ref (examples): loadMicroPython(), runPython(), runPythonAsync()
  // https://cdn.jsdelivr.net/npm/@micropython/micropython-webassembly-pyscript/
  import * as mpjs from 'https://cdn.jsdelivr.net/npm/@micropython/micropython-webassembly-pyscript@1.26.0/micropython.mjs';

  const runBtn = document.getElementById('run');
  const testBtn = document.getElementById('tests');
  const out = document.getElementById('out');
  const status = document.getElementById('status');
  const codeEl = document.getElementById('code');

  function log(line = "") { out.textContent += line + "\n"; }

  // Load the MicroPython runtime (the .mjs will fetch micropython.wasm next to it)
  let mp;
  try {
    mp = await mpjs.loadMicroPython();
    status.textContent = 'Ready.';
    runBtn.textContent = 'Run Python';
    runBtn.disabled = false;
    testBtn.disabled = false;
  } catch (e) {
    status.textContent = 'Failed to initialize MicroPython';
    log(String(e && e.message ? e.message : e));
    throw e;
  }

  // ----- stdout capture shim -----
  // For consistency with your previous code (which relied on do_str() returning stdout),
  // we temporarily redirect sys.stdout to a StringIO buffer per run.
  async function runAndCaptureStdout(pySrc) {
    const src = pySrc.endsWith('\n') ? pySrc : pySrc + '\n';
    await mp.runPythonAsync('import sys, io\n__cap_buf__ = io.StringIO()\n__cap_prev__ = sys.stdout\nsys.stdout = __cap_buf__');
    let captured = '';
    try {
      await mp.runPythonAsync(src);
      captured = await mp.runPythonAsync('__cap_buf__.getvalue()');
    } finally {
      await mp.runPythonAsync('sys.stdout = __cap_prev__');
    }
    return String(captured ?? '');
  }

  runBtn.addEventListener('click', async () => {
    runBtn.disabled = true;
    status.textContent = 'Running…';
    out.textContent = '';
    try {
      const stdout = await runAndCaptureStdout(codeEl.value);
      if (stdout) log(stdout.trimEnd());
    } catch (err) {
      log(String(err && err.message ? err.message : err));
    } finally {
      status.textContent = 'Ready.';
      runBtn.disabled = false;
    }
  });

  // ----- Tests (existing preserved; new ones appended) -----
  testBtn.addEventListener('click', async () => {
    testBtn.disabled = true;
    out.textContent = '';
    status.textContent = 'Running tests…';

    const results = [];
    const record = (name, pass, info = '') => {
      results.push({ name, pass, info });
      log(`${pass ? '✔' : '✖'} ${name}${info ? ' — ' + info : ''}`);
    };

    try {
      // (1) prints hello world — DO NOT MODIFY (existing test)
      {
        const stdout = await runAndCaptureStdout("print('hello world')\n");
        record('prints hello world', stdout.trim() === 'hello world', `got: ${JSON.stringify(stdout.trim())}`);
      }
      // (2) arithmetic — DO NOT MODIFY (existing test)
      {
        const stdout = await runAndCaptureStdout('print(1+2)\n');
        record('arithmetic 1+2 == 3', stdout.trim() === '3', `got: ${JSON.stringify(stdout.trim())}`);
      }
      // (3) state persists — DO NOT MODIFY (existing test)
      {
        await mp.runPythonAsync('x=41\n');
        const stdout = await runAndCaptureStdout('print(x+1)\n');
        record('state persists across runs', stdout.trim() === '42', `got: ${JSON.stringify(stdout.trim())}`);
      }
      // (4) exceptions propagate — DO NOT MODIFY (existing test)
      {
        let raised = false;
        try { await mp.runPythonAsync("raise ValueError('boom')\n"); } catch (_) { raised = true; }
        record('exceptions propagate to JS', raised, raised ? '' : 'expected rejection');
      }

      // (5) NEW — stdlib math sanity
      {
