  // phase is the one that expired
  constructor(public readonly roundId: RoundId, public readonly phase: RoundPhase, public readonly at: TimePoint) {}
  async execute(ctx: CommandContext): Promise<void> {
    const state = await ctx.gateway.loadRoundState(this.roundId);
