use axum::{
    extract::Request,
    http::StatusCode,
    response::{Html, IntoResponse},
    routing::{get, get_service},
    Router,
};
use std::{net::SocketAddr, path::PathBuf};
use tower_http::services::ServeDir;

#[tokio::main]
async fn main() {
    // Path to your built SPA assets (e.g. dist/ or build/)
    let assets_dir = PathBuf::from("./dist");

    // Serve static files (e.g. JS, CSS)
    let static_files = get_service(ServeDir::new(&assets_dir)).handle_error(|_| async {
        (StatusCode::INTERNAL_SERVER_ERROR, "Static file error").into_response()
    });

    // Main router
    let app = Router::new()
        // API routes first
        .route("/api/health", get(|| async { "OK" }))
        // Serve static files
        .nest_service("/assets", static_files.clone())
        // Fallback route: serve index.html for all other GET requests
        .fallback_service(get(move |req: Request| async move {
            serve_index(req, assets_dir.clone()).await
        }));

    let addr = SocketAddr::from(([127, 0, 0, 1], 3000));
    println!("Server running at http://{}", addr);
    axum::serve(tokio::net::TcpListener::bind(addr).await.unwrap(), app)
        .await
        .unwrap();
}

async fn serve_index(_req: Request, assets_dir: PathBuf) -> impl IntoResponse {
    let index_path = assets_dir.join("index.html");
    match tokio::fs::read_to_string(index_path).await {
        Ok(content) => Html(content).into_response(),
        Err(_) => (StatusCode::NOT_FOUND, "index.html not found").into_response(),
    }
}

