// Compute base path (for GitHub Pages compatibility)
const APP_ROOT = (() => {
    // If deployed under subpath, derive it
    const path = window.location.pathname;
    const match = path.match(/^(\/[^/]+\/)/); // e.g. "/myapp/"
    return match ? match[1] : '/';
})();

function navigateTo(path) {
    const targetUrl = APP_ROOT + path.replace(/^\//, '');
    history.pushState({}, '', targetUrl);
    handleRouteChange();
}

function handleRouteChange() {
    const path = window.location.pathname.replace(APP_ROOT, '');
    const [route] = path.split('/'); // e.g. "hosts", "clients", or ""

    // Hide all views
    document.querySelectorAll('.view').forEach(v => v.classList.add('hidden'));

    switch (route) {
        case 'hosts':
            document.getElementById('view-hosts')?.classList.remove('hidden');
            break;
        case 'clients':
            document.getElementById('view-clients')?.classList.remove('hidden');
            break;
        default:
            document.getElementById('view-home')?.classList.remove('hidden');
            break;
    }
}

// Handle back/forward navigation
window.addEventListener('popstate', handleRouteChange);

// Run on page load
document.addEventListener('DOMContentLoaded', () => {
    handleRouteChange();
});

