import java.util.function.IntConsumer;

class ZeroEvenOdd {
    private final int n;
    private boolean lastIsZero = false;
    private int last = 0;

    public ZeroEvenOdd(int n) {
        this.n = n;
    }

    public synchronized void zero(IntConsumer printNumber) throws InterruptedException {
        while (last < n) {
            while (lastIsZero) this.wait();
            if (last < n) {
                printNumber.accept(0);
                lastIsZero = true;
                this.notifyAll();
            }
        }
    }

    public synchronized void even(IntConsumer printNumber) throws InterruptedException {
        int max = (n % 2 == 0) ? n : n - 1;
        while (last < max) {
            while (!lastIsZero || (this.last % 2 == 0)) this.wait();
            printNumber.accept(++last);
            lastIsZero = false;
            this.notifyAll();
        }
    }

    public synchronized void odd(IntConsumer printNumber) throws InterruptedException {
        int max = (n % 2 == 1) ? n : n - 1;
        while (last < max) {
            while (!lastIsZero || (this.last % 2 == 1)) this.wait();
            printNumber.accept(++last);
            lastIsZero = false;
            this.notifyAll();
        }
    }

    public static void main(String[] args) throws InterruptedException {
        ZeroEvenOdd x = new ZeroEvenOdd(7);

        StringBuffer sb = new StringBuffer(); // thread-safe
        IntConsumer p = sb::append;

        Thread t0 = new Thread(() -> runChecked(() -> x.zero(p)), "zero");
        Thread t1 = new Thread(() -> runChecked(() -> x.odd(p)),  "odd");
        Thread t2 = new Thread(() -> runChecked(() -> x.even(p)), "even");

        Thread.UncaughtExceptionHandler ueh = (t, e) ->
                System.err.println("Thread " + t.getName() + " died: " + e);

        t0.setUncaughtExceptionHandler(ueh);
        t1.setUncaughtExceptionHandler(ueh);
        t2.setUncaughtExceptionHandler(ueh);

        t0.start(); t1.start(); t2.start();
        t0.join();  t1.join();  t2.join();

        System.out.println(sb.toString()); // print once, complete
    }

    @FunctionalInterface
    interface CheckedRunnable { void run() throws InterruptedException; }

    static void runChecked(CheckedRunnable r) {
        try {
            r.run();
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt(); // preserve interrupt
            throw new RuntimeException(e);
        }
    }
}

