            // --- 3. Mix active or releasing voices ---
            if (v.isActive() || v.isReleasing()) {
                float pan = v.getPan();
                float leftGain  = (pan <= 0f) ? 1f : 1f - pan;
                float rightGain = (pan >= 0f) ? 1f : 1f + pan;

                // Mix voice sample into output
                channels[0] += sample * leftGain;
                if (channels.length > 1)
