import { promises as fs } from 'fs';
import oldModels from './models.json' assert { type: "json" };
import newModels from './models.new.json' assert { type: "json" };

async function compareAndGenerateMD() {
    const newModelNames = newModels.map(model => model.name);
    const oldModelNames = oldModels.map(model => model.name);

    const addedModels = newModels.filter(model => !oldModelNames.includes(model.name));
    const removedModels = oldModels.filter(model => !newModelNames.includes(model.name));

    const activeModels = newModels.map(newModel => {
        const oldModel = oldModels.find(m => m.name === newModel.name);
        const runCountDiff = oldModel ? newModel.run_count - oldModel.run_count : newModel.run_count;
        return { ...newModel, runCountDiff };
    })
    .filter(model => model.runCountDiff > 100)
    .sort((a, b) => b.runCountDiff - a.runCountDiff);

    let markdownContent = '# Model Stats\n';

    // New Models
