    for (let model of removedModels) {
        markdownContent += `- ${model.name}\n`;
    }

    // Active Models
    markdownContent += '\n## Active Models\n';
    for (let model of activeModels) {
        markdownContent += `- ${model.name} (Difference in run count: ${model.runCountDiff})\n`;
    }

    // Write to stats.md
