I got this command line script, can you write a pysimplegui script for it? I suggest making the LANGUAGES into dropdown, I hope you can figure out from the double while loop how it should work ... thanks. Also if you can adopt the styles a bit to make it look nice, default fonts tend to be quite small.

from googletrans import Translator, LANGUAGES

def main():
    while True:
        target = input("Choose a language to translate to (type 'q' to exit): ")
        if target == "q":
            break
        if target not in LANGUAGES:
            print(f'Invalid target language, valid are: {", ".join(LANGUAGES)}')
            continue

        while True:
            text = input(
                f"Enter text to translate to {LANGUAGES[target]} (type 'q' to change language): "
            )
            if text == "q":
                break
            translated = translate_text(text, target=target)
            print(translated)

def translate_text(text, target="en"):
    translator = Translator()
    translation = translator.translate(text, dest=target)
    return translation.text

if __name__ == "__main__":
    main()

