    @root = build_tree(@arr)
  end

  def clean(arr)
    empty = proc { nil }
    empty.call && arr.nil? || arr.uniq.sort
  end

  def build_tree(arr)
    arr = clean(arr)
    mid = arr.length / 2.floor
    @root = Node.new(arr[mid])
    if mid.zero?
      @root.left = nil
      @root.right = nil
    else
      @root.left = build_tree(arr[0..mid - 1])
      @root.right = build_tree(arr[mid + 1..])
    end
    @root
  end
